// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"ode-intro":{"id":"ode-intro","prerequisites":["derivative-exp","higher-derivatives","antiderivative"],"next":["initial-value-problem"],"related":["separation-of-variables"],"objectives":["說得出微分方程的未知數是一個函數，解是「代進去讓等式對每個 $x$ 都成立」的函數。","會判斷方程的階，並把候選函數代進去檢查它是不是解。","知道 $y'=ky$ 的解是 $Ce^{kx}$，一個一階方程通常有一整族解。"],"concept":[{"heading":"① 未知數是一個函數","body":["代數方程 $x^2=4$ 的未知數是一個數。微分方程的未知數是一個函數 $y(x)$，方程裡出現它的導數，例如 $y'=2y$。","這條方程在說：$y$ 在每一點的變化率，等於它當下值的兩倍。解就是滿足這件事的函數，而且要在一整個區間上每個 $x$ 都成立，不是只在某一點成立。"]},{"heading":"② 檢查一個解：代進去","body":["$y=3e^{2x}$：$y'=6e^{2x}=2\\cdot3e^{2x}=2y$，所以是解。","換成 $5e^{2x}$、$-e^{2x}$、甚至 $0$ 也都成立。$y'=2y$ 的解是一整族 $y=Ce^{2x}$，$C$ 是任意常數。一般來說 $y'=ky$ 的解是 $Ce^{kx}$：變化率跟自己成正比的量，就是指數。"]},{"heading":"③ 階：出現的最高導數","body":["$y'=2y$ 是一階，$y''+4y=0$ 是二階。看的是導數的次數，不是 $x$ 的次方：$y'=x^5$ 仍是一階。","只有一個自變數 $x$ 的叫常微分方程（ODE）；有好幾個自變數、出現偏導數的叫偏微分方程，不在這一章。","一階方程的一族解通常帶一個任意常數，二階通常帶兩個。要從中挑出一條，就要額外的條件（〈初值問題〉）。"]},{"heading":"④ 圖像：斜率場","body":["$y'=f(x,y)$ 在每一點 $(x,y)$ 都告訴你「經過這裡的解曲線，斜率是多少」。把每點的斜率畫成一小段線，就是斜率場。解曲線就是順著這些小線段走的曲線。","這是直觀，不是解法：它讓你在還不會解之前，先看出解大概長什麼樣、往哪裡去。"]}],"workedExamples":[{"title":"代進去檢查","prompt":"$y=3e^{2x}$ 是不是 $y'=2y$ 的解？","steps":["算左邊：$y'=3\\cdot2e^{2x}=6e^{2x}$（連鎖律）。","算右邊：$2y=2\\cdot3e^{2x}=6e^{2x}$。","兩邊對每個 $x$ 都相等，所以是解。"],"answer":"是"},{"title":"二階方程","prompt":"$y=\\cos 2x$ 是不是 $y''+4y=0$ 的解？這條方程是幾階？","steps":["最高出現 $y''$，是二階。","$y'=-2\\sin 2x$，$y''=-4\\cos 2x$。","$y''+4y=-4\\cos 2x+4\\cos 2x=0$，對每個 $x$ 都成立，是解。"],"answer":"是解；二階"},{"title":"一整族解","prompt":"證明對任何常數 $C$，$y=x-1+Ce^{-x}$ 都是 $y'=x-y$ 的解。","steps":["左邊：$y'=1-Ce^{-x}$。","右邊：$x-y=x-(x-1+Ce^{-x})=1-Ce^{-x}$。","兩邊相同，而且推導時沒有用到 $C$ 是多少，所以每個 $C$ 都成立。","$C=0$ 給直線 $y=x-1$；$C\\ne 0$ 時 $Ce^{-x}$ 隨 $x\\to\\infty$ 趨近 $0$，所以每條解最後都貼近這條直線，這就是斜率場裡看到的現象。"],"answer":"對所有 $C$ 都成立","note":"機器驗算取 $C=2$ 與 $C=-5$ 兩個代表；對一般 $C$ 的論證在步驟裡。"}],"pitfalls":["把階和次方搞混：$(y')^3=x$ 仍是一階，$y'=x^5$ 也是一階。","只在一個點檢查就說是解；要對整個區間的每個 $x$ 都成立。","以為解只有一個；一階方程通常有一整族解，差一個常數。","把 $y'=2y$ 的解寫成 $y=2x+C$：那是 $y'=2$ 的解。"],"checks":[{"ask":"$y''+3y'=x^5$ 是幾階微分方程？","options":[{"label":"二階","correct":true},{"label":"五階","why":"$5$ 是 $x$ 的次方，不是導數的次數；最高導數是 $y''$。"},{"label":"一階","why":"$y'$ 是一階沒錯，但方程裡還有 $y''$，看最高的那一個。"}]},{"ask":"下列哪一個是 $y'=-y$ 的解？","options":[{"label":"$y=e^{-x}$","correct":true},{"label":"$y=e^x$","why":"$y'=e^x$，而 $-y=-e^x$，差一個負號。"},{"label":"$y=-x$","why":"$y'=-1$，而 $-y=x$，只有 $x=-1$ 那一點相等，不是每個 $x$ 都成立。"}]},{"ask":"微分方程 $y'=2y$ 的「解」是什麼東西？","options":[{"label":"一個函數，代進去之後等式對每個 $x$ 都成立","correct":true},{"label":"一個數","why":"未知數是 $y(x)$ 這個函數，不是某個數；代數方程才是解出數。"},{"label":"讓等式成立的某個 $x$ 值","why":"那是把它當成 $x$ 的方程在解；這裡要的是整個函數。"}]},{"ask":"$y'=ky$（$k$ 是常數）的所有解是？","options":[{"label":"$y=Ce^{kx}$，$C$ 任意","correct":true},{"label":"$y=kx+C$","why":"這個函數的導數是常數 $k$，不會跟 $y$ 成正比；那是 $y'=k$ 的解。"},{"label":"$y=e^{kx}+C$","why":"常數要乘在前面：$(e^{kx}+C)'=ke^{kx}$，但 $k(e^{kx}+C)$ 多了 $kC$。"}]}],"practice":[{"id":"ode-sep-001","core":true},{"id":"gap-der-ode-002","core":true},{"id":"cx-ode-001"}]},"initial-value-problem":{"id":"initial-value-problem","prerequisites":["ode-intro"],"next":["separation-of-variables"],"related":["second-order-linear"],"objectives":["用初始條件從一整族解裡定出常數，條件不在 $x=0$ 也會做。","說出解只在某個區間上存在，會找出含初始點的那段區間。","知道一階要一個條件、二階要兩個條件，並說得出存在唯一定理要求什麼。"],"concept":[{"heading":"① 從一族解裡挑一條","body":["$y'=2y$ 的解是 $y=Ce^{2x}$，每個 $C$ 是一條曲線。再加一句「$y(0)=3$」，意思是：要通過點 $(0,3)$ 的那一條。代進去 $3=Ce^0=C$，答案 $y=3e^{2x}$。","微分方程加上初始條件，叫初值問題。做法永遠是兩步：先找出帶常數的一族解，再用條件定常數。"]},{"heading":"② 條件不在 $0$ 也一樣","body":["$y(1)=2$ 就是代 $x=1$：$2=Ce^3$，$C=2e^{-3}$，$y=2e^{3(x-1)}$（以 $y'=3y$ 為例）。不要把 $2$ 直接當成 $C$；只有條件給在 $x=0$、而且一族解在 $0$ 的值剛好是 $C$ 時，兩者才相等。"]},{"heading":"③ 解不一定活在整條數線上","body":["$y'=y^2$、$y(0)=1$ 的解是 $y=\\frac{1}{1-x}$（〈分離變數〉會推導）。代回去：$y'=\\frac{1}{(1-x)^2}=y^2$，$y(0)=1$。","但 $x\\to1^-$ 時 $y\\to\\infty$。公式在 $x>1$ 也有值，可是那一支和 $(0,1)$ 中間隔著一個斷點，解不能跳過去。所以這個初值問題的解只活在 $x<1$。方程看起來很溫和，解卻在有限的距離內衝到無窮大，這叫爆破。","所以初值問題的答案要包含區間：含初始點、而且解在上面好好定義的最大區間。"]},{"heading":"④ 二階要兩個條件","body":["二階方程的一族解有兩個常數，例如 $y''+y=0$ 的解是 $A\\cos x+B\\sin x$。一個條件只定得出一個常數，所以要給兩個：通常是 $y(x_0)$ 與 $y'(x_0)$，物理上就是起始位置與起始速度（〈二階線性〉）。"]},{"heading":"存在唯一定理（一階）","body":["考慮 $y'=f(x,y)$、$y(x_0)=y_0$。若 $f$ 與 $\\frac{\\partial f}{\\partial y}$ 在某個包含 $(x_0,y_0)$ 的矩形裡連續，則存在一個包含 $x_0$ 的區間，上面恰好有一個解。","注意兩點。第一，定理只保證「某個區間」，不保證整條數線：$y'=y^2$ 的 $f=y^2$ 處處連續，解仍然在 $x=1$ 爆破。第二，條件不成立時唯一性可能失敗：$y'=3y^{2/3}$、$y(0)=0$ 同時有 $y=0$ 與 $y=x^3$ 兩個解；這裡 $\\frac{\\partial f}{\\partial y}=2y^{-1/3}$ 在 $y=0$ 不連續。"],"collapsible":true}],"workedExamples":[{"title":"條件在 $x=0$","prompt":"$y'=-2y$，$y(0)=5$。","problemId":"cx-ode-002","steps":["$y'=ky$ 的解是 $Ce^{kx}$，這裡 $k=-2$：$y=Ce^{-2x}$。","代 $x=0$：$5=Ce^0=C$。","$y=5e^{-2x}$。指數部分處處有定義，解在整條數線上都存在。"],"answer":"$y=5e^{-2x}$"},{"title":"條件不在 $0$","prompt":"$y'=3y$，$y(1)=2$。","steps":["一族解：$y=Ce^{3x}$。","代 $x=1$：$2=Ce^3$，所以 $C=\\frac{2}{e^3}=2e^{-3}$。","$y=2e^{-3}\\cdot e^{3x}=2e^{3(x-1)}$。","檢查：$x=1$ 時 $2e^0=2$。"],"answer":"$y=2e^{3(x-1)}$"},{"title":"會爆破的解","prompt":"驗證 $y=\\frac{1}{1-x}$ 是 $y'=y^2$、$y(0)=1$ 的解，並求它存在的區間。","problemId":"ode-sep-003","steps":["$y=(1-x)^{-1}$，$y'=-(1-x)^{-2}\\cdot(-1)=\\frac{1}{(1-x)^2}$。","$y^2=\\frac{1}{(1-x)^2}$，和 $y'$ 相同。$y(0)=\\frac{1}{1}=1$。","$x=1$ 時分母為 $0$。含 $x=0$ 而且沒有斷點的最大區間是 $(-\\infty,1)$。","$x\\to1^-$ 時 $y\\to+\\infty$：解在 $x=1$ 之前就爆破了。"],"answer":"$y=\\frac{1}{1-x}$，$x<1$"}],"pitfalls":["條件給 $y(1)=2$，卻直接寫 $C=2$。","忘了寫區間：$y=\\frac{1}{1-x}$ 這個初值問題的解只在 $x<1$。","二階方程只用一個條件，留下一個沒定的常數。","先代條件再積分：要先得到帶常數的一族解，最後才代條件。"],"checks":[{"ask":"$y=Ce^{4x}$，$y(0)=7$，$C$ 是？","options":[{"label":"$7$","correct":true},{"label":"$4$","why":"$4$ 是指數裡的 $k$，由方程決定；$C$ 由條件決定。"},{"label":"$7e^{-4}$","why":"那是條件給在 $x=1$ 時的答案；這裡 $x=0$，$e^0=1$。"}]},{"ask":"$y=Ce^{2x}$，$y(1)=e^2$，$C$ 是？","options":[{"label":"$1$","correct":true},{"label":"$e^2$","why":"直接把 $y$ 值當成 $C$ 只在 $x=0$ 成立；這裡要解 $Ce^2=e^2$。"},{"label":"$e^4$","why":"$C$ 要除以 $e^{2\\cdot1}$，不是乘：$Ce^2=e^2$ 得 $C=1$。"}]},{"ask":"$y'=y^2$、$y(0)=1$ 的解 $y=\\frac{1}{1-x}$，存在的區間是？","options":[{"label":"$x<1$","correct":true},{"label":"所有實數","why":"$x=1$ 時分母為 $0$，解在那裡衝到無窮大，過不去。"},{"label":"$x>1$","why":"那一支不含初始點 $x=0$，和 $(0,1)$ 隔著斷點，不是這個初值問題的解。"}]},{"ask":"二階方程 $y''+y=0$ 要確定唯一一個解，需要什麼？","options":[{"label":"$y(x_0)$ 與 $y'(x_0)$ 兩個條件","correct":true},{"label":"只要 $y(x_0)$","why":"一族解 $A\\cos x+B\\sin x$ 有兩個常數，一個條件只能定一個。"},{"label":"不需要條件，解是唯一的","why":"$\\cos x$、$\\sin x$、$2\\cos x$ 都是解，沒有條件挑不出哪一個。"}]}],"practice":[{"id":"gap-der-ode-001","core":true},{"id":"cx-ode-002","core":true},{"id":"ode-val-001","core":true},{"id":"gap-der-ode-002","core":true},{"id":"ode-h2-002","note":"一族解 $A\\cos x+B\\sin x$ 已知時，用兩個條件定 $A$、$B$。"},{"id":"ode-sep-003","challenge":true,"note":"挑戰：要先會〈分離變數〉；注意解只活在 $x<1$。"}]},"separation-of-variables":{"id":"separation-of-variables","prerequisites":["initial-value-problem","u-sub-basic","partial-fractions-linear"],"next":["first-order-linear"],"related":["chain-rule"],"objectives":["認出 $y'=g(x)h(y)$ 的形狀，把 $y$ 搬到一邊、$x$ 搬到另一邊，兩邊各自積分。","處理 $\\ln|y|$ 與絕對值，把常數整理成一個任意常數，再用初始條件定出來。","不漏掉除以 $h(y)$ 時丟掉的平衡解。"],"concept":[{"heading":"① 能分開的形狀","body":["如果 $y'$ 能寫成「只含 $x$ 的函數」乘「只含 $y$ 的函數」：$\\frac{dy}{dx}=g(x)h(y)$，就叫可分離。例如 $y'=2xy$（$g=2x$、$h=y$）、$y'=\\frac{x}{y}$、$y'=y^2$。","$y'=x+y$ 不行：加法拆不成乘積。"]},{"heading":"② 做法：$y$ 一邊、$x$ 一邊，各自積分","body":["在 $h(y)\\ne 0$ 的地方，寫成 $\\frac{dy}{h(y)}=g(x)\\,dx$，兩邊積分：$\\int\\frac{dy}{h(y)}=\\int g(x)\\,dx+C$。只要一個常數，放在一邊就好。","把 $dy$、$dx$ 拆開只是記號。真正的理由是連鎖律：設 $H'(y)=\\frac{1}{h(y)}$，則 $\\frac{d}{dx}H(y(x))=\\frac{y'}{h(y)}=g(x)$，所以 $H(y)$ 是 $g$ 的反導函數，差一個常數。"],"tex":["\\frac{dy}{dx}=g(x)\\,h(y)\\ \\Longrightarrow\\ \\int\\frac{dy}{h(y)}=\\int g(x)\\,dx+C"]},{"heading":"③ 絕對值與常數","body":["$y'=2xy$：$\\int\\frac{dy}{y}=\\int 2x\\,dx$，得 $\\ln|y|=x^2+C$。取指數：$|y|=e^Ce^{x^2}$，所以 $y=\\pm e^Ce^{x^2}$。$\\pm e^C$ 可以是任何非零的數，記成 $A$：$y=Ae^{x^2}$（$A\\ne 0$）。"]},{"heading":"④ 除以 $h(y)$ 時丟掉的解","body":["第二步除以了 $h(y)$，等於先假設 $h(y)\\ne 0$。但若 $h(y_0)=0$，常數函數 $y=y_0$ 的兩邊都是 $0$，它也是解，叫平衡解。","$y'=2xy$ 的平衡解是 $y=0$，剛好是上面公式 $A=0$ 的情形，所以最後寫 $y=Ae^{x^2}$、$A$ 任意。但不一定都能這樣補回來：$y'=y^2$ 的分離結果是 $y=-\\frac{1}{x+C}$，沒有任何 $C$ 讓它等於 $0$，平衡解 $y=0$ 必須另外列出。"]}],"workedExamples":[{"title":"指數型","prompt":"$y'=2xy$，$y(0)=1$。","problemId":"ode-sep-002","steps":["可分離：$g(x)=2x$、$h(y)=y$。","$y\\ne 0$ 時：$\\int\\frac{dy}{y}=\\int 2x\\,dx$，$\\ln|y|=x^2+C$。","整理成 $y=Ae^{x^2}$，$A$ 任意（$A=0$ 是平衡解 $y=0$）。","代 $y(0)=1$：$A=1$，$y=e^{x^2}$。"],"answer":"$y=e^{x^2}$"},{"title":"用初始條件選正負號","prompt":"$y'=\\frac{x}{y}$，$y(0)=2$。","problemId":"ode-sep-004","steps":["$y\\,dy=x\\,dx$，兩邊積分：$\\frac{y^2}{2}=\\frac{x^2}{2}+C$，即 $y^2=x^2+K$（$K=2C$）。","代 $x=0$、$y=2$：$4=K$，所以 $y^2=x^2+4$。","$y=\\pm\\sqrt{x^2+4}$。初始值 $y=2>0$，選正號：$y=\\sqrt{x^2+4}$。","$x^2+4>0$，所以解在整條數線上都有定義，而且 $y$ 永遠不等於 $0$（方程裡除以 $y$ 沒問題）。"],"answer":"$y=\\sqrt{x^2+4}$"},{"title":"邏輯斯方程：要用部分分式","prompt":"$y'=y(1-y)$，$y(0)=\\frac{1}{2}$。","problemId":"ode-sep-006","steps":["平衡解：$y(1-y)=0$，即 $y=0$ 與 $y=1$。初始值 $\\frac{1}{2}$ 不是平衡解，以下 $0<y<1$。","$\\int\\frac{dy}{y(1-y)}=\\int dx$。部分分式：$\\frac{1}{y(1-y)}=\\frac{1}{y}+\\frac{1}{1-y}$。","$\\ln|y|-\\ln|1-y|=x+C$，即 $\\frac{y}{1-y}=Ae^x$。","代 $y(0)=\\frac{1}{2}$：$\\frac{1/2}{1/2}=1=A$。","$y=e^x(1-y)$，解出 $y=\\frac{e^x}{1+e^x}=\\frac{1}{1+e^{-x}}$。$x\\to\\infty$ 時 $y\\to1$，正是斜率場裡往 $y=1$ 貼近的那條曲線。"],"answer":"$y=\\frac{1}{1+e^{-x}}$"}],"pitfalls":["直接對 $x$ 積分 $\\int y^2\\,dx$，右邊還留著 $y$：要先把 $y$ 全搬到左邊。","$\\ln|y|=x+C$ 取指數寫成 $y=e^x+C$：指數的和是乘積，應為 $Ae^x$。","除以 $h(y)$ 後忘了檢查平衡解（例如 $y'=y^2$ 的 $y=0$）。","$y^2=x^2+4$ 開根號時不管正負，要用初始條件選。","兩邊各加一個常數，最後多出兩個常數；合併成一個就好。"],"checks":[{"ask":"下列哪一個方程可分離？","options":[{"label":"$y'=x^2y$","correct":true},{"label":"$y'=x+y$","why":"加法拆不成 $g(x)h(y)$ 的乘積；它是一階線性（〈一階線性〉）。"},{"label":"$y'=\\sin(xy)$","why":"$x$、$y$ 綁在同一個 $\\sin$ 裡，拆不開。"}]},{"ask":"解 $y'=y^2$ 時把兩邊除以 $y^2$，可能漏掉哪個解？","options":[{"label":"$y=0$","correct":true},{"label":"$y=1$","why":"$y=1$ 時 $y'=0$ 但 $y^2=1$，不是解。"},{"label":"沒有漏掉","why":"$y=0$ 讓兩邊都是 $0$，是解；而分離出來的 $y=-\\frac{1}{x+C}$ 永遠不等於 $0$。"}]},{"ask":"$\\ln|y|=x+C$ 化簡後，所有解（含平衡解 $y=0$）可以寫成？","options":[{"label":"$y=Ae^x$，$A$ 任意","correct":true},{"label":"$y=e^x+C$","why":"$e^{x+C}=e^C\\cdot e^x$，常數是乘上去的，不是加上去的。"},{"label":"$y=x+e^C$","why":"取指數要對整個等式做：$|y|=e^{x+C}$。"}]},{"ask":"$y'=\\frac{x}{y}$，$y(0)=-2$ 的解是？","options":[{"label":"$y=-\\sqrt{x^2+4}$","correct":true},{"label":"$y=\\sqrt{x^2+4}$","why":"這條在 $x=0$ 時是 $+2$，不滿足 $y(0)=-2$。"},{"label":"$y=\\pm\\sqrt{x^2+4}$","why":"初值問題只要一條解；正負號由 $y(0)=-2$ 決定。"}]}],"practice":[{"id":"ode-sep-002","core":true},{"id":"ode-val-005","core":true},{"id":"ode-sep-004","core":true},{"id":"ode-sep-005","core":true},{"id":"ode-sep-008","core":true},{"id":"ode-sep-007","core":true},{"id":"ode-val-002"},{"id":"ode-sep-003","note":"$y'=y^2$：注意解只活在 $x<1$。"},{"id":"ode-sep-006"},{"id":"ode-val-006","challenge":true,"note":"挑戰：$\\int\\sin x\\,dx$ 的符號，最後代到 $x=\\pi$。"}]},"first-order-linear":{"id":"first-order-linear","prerequisites":["separation-of-variables"],"next":["integrating-factor"],"related":["second-order-linear"],"objectives":["判斷一個一階方程是不是線性，並化成標準形 $y'+P(x)y=Q(x)$，正確讀出 $P$ 與 $Q$。","解齊次的情形 $y'+P(x)y=0$，並說出通解 $={}$ 齊次通解 $+$ 一個特解的理由。","解常數係數的 $y'+ay=b$，用平衡值說出長期行為（例如牛頓冷卻）。"],"concept":[{"heading":"① 什麼叫線性","body":["一階線性方程可以整理成 $y'+P(x)y=Q(x)$：$y$ 和 $y'$ 都只出現一次方、沒有互乘、不被包在函數裡，係數只跟 $x$ 有關。","線性：$xy'+y=x^2$、$y'=-y\\tan x$、$y'=x+y$。不是線性：$y'=y^2$（平方）、$yy'=x$（互乘）、$y'=\\sin y$（包在函數裡）。"]},{"heading":"② 先化成標準形","body":["$y'$ 的係數要是 $1$，含 $y$ 的項全部移到左邊。$y'=x+y$ 要寫成 $y'-y=x$，所以 $P=-1$，不是 $+1$。$xy'+y=x^2$（$x>0$）要先除以 $x$：$y'+\\frac{1}{x}y=x$，$P=\\frac{1}{x}$、$Q=x$。"]},{"heading":"③ 齊次的情形就是可分離","body":["$Q=0$ 時 $y'=-P(x)y$，用〈分離變數〉：$y=Ce^{-\\int P\\,dx}$。例如 $y'+2y=0$ 的解是 $Ce^{-2x}$。"]},{"heading":"④ 解的結構：齊次通解加一個特解","body":["假設已經找到一個解 $y_p$。任何其他解 $y$ 和它相減：$(y-y_p)'+P(y-y_p)=Q-Q=0$，所以差是齊次方程的解，等於 $Ce^{-\\int P\\,dx}$。","結論：通解 $=y_p+Ce^{-\\int P\\,dx}$。只要找到一個特解，加上齊次通解，就是全部的解。這是「線性」帶來的好處，非線性方程沒有。找特解的系統方法在〈積分因子〉。"]},{"heading":"⑤ 常數係數：平衡值","body":["$y'+ay=b$（$a\\ne 0$）有一個常數解 $y=\\frac{b}{a}$（代進去 $0+b=b$）。所以 $y=\\frac{b}{a}+Ce^{-ax}$。$a>0$ 時 $e^{-ax}\\to0$，每一條解都趨近 $\\frac{b}{a}$。","牛頓冷卻 $T'=-k(T-T_0)$ 就是這個形狀：溫差以指數速度消失，溫度趨近室溫 $T_0$。"]}],"workedExamples":[{"title":"常數係數","prompt":"$y'+2y=4$，$y(0)=0$。","problemId":"ode-lin-003","steps":["常數解：$2y=4$，$y=2$。齊次 $y'+2y=0$ 的解是 $Ce^{-2x}$。","通解 $y=2+Ce^{-2x}$。","代 $y(0)=0$：$2+C=0$，$C=-2$。","$y=2-2e^{-2x}$。$x\\to\\infty$ 時趨近 $2$。"],"answer":"$y=2-2e^{-2x}$"},{"title":"化成標準形，再組合解","prompt":"$xy'+y=x^2$，$y(1)=1$（$x>0$）。已知 $y_p=\\frac{x^2}{3}$ 是一個特解。","problemId":"ode-lin-004","steps":["除以 $x$：$y'+\\frac{1}{x}y=x$，$P=\\frac{1}{x}$、$Q=x$。","檢查特解：$y_p'+\\frac{y_p}{x}=\\frac{2x}{3}+\\frac{x}{3}=x$。✔","齊次通解：$e^{-\\int(1/x)\\,dx}=e^{-\\ln x}=\\frac{1}{x}$（$x>0$），所以是 $\\frac{C}{x}$。","通解 $y=\\frac{x^2}{3}+\\frac{C}{x}$。代 $y(1)=1$：$\\frac{1}{3}+C=1$，$C=\\frac{2}{3}$。","$y=\\frac{x^2}{3}+\\frac{2}{3x}=\\frac{x^3+2}{3x}$。"],"answer":"$y=\\frac{x^3+2}{3x}$"},{"title":"牛頓冷卻","prompt":"物體 100°C 放進 20°C 的房間，10 分鐘後 60°C。設 $T'=-k(T-20)$，求 20 分鐘後的溫度。","problemId":"ap-gro-004","steps":["這是 $T'+kT=20k$，平衡值 $T=20$。通解 $T=20+Ce^{-kt}$。","$T(0)=100$：$C=80$。","$T(10)=60$：$80e^{-10k}=40$，所以 $e^{-10k}=\\frac{1}{2}$。","$T(20)=20+80e^{-20k}=20+80\\cdot\\left(\\frac{1}{2}\\right)^2=40$。溫差每 10 分鐘減半：$80\\to40\\to20$。"],"answer":"40°C","note":"驗算把 $t$ 寫成 $x$，$k=\\frac{\\ln 2}{10}$。"}],"pitfalls":["$y'=3y+x$ 直接讀成 $P=3$：移項後是 $y'-3y=x$，$P=-3$。","$y'$ 前面有係數（例如 $xy'$）就讀 $P$，沒有先除掉。","只寫特解，忘了加齊次通解，結果配不上初始條件。","把 $y'=y^2$ 當成線性：$y$ 的平方不是線性項。"],"checks":[{"ask":"下列哪一個是一階線性方程？","options":[{"label":"$y'+x^2y=\\sin x$","correct":true},{"label":"$y'+y^2=x$","why":"$y^2$ 不是一次方，非線性。"},{"label":"$yy'=x$","why":"$y$ 和 $y'$ 互乘，非線性（它是可分離的）。"}]},{"ask":"$y'=3y+x$ 化成 $y'+P(x)y=Q(x)$，$P$ 是？","options":[{"label":"$-3$","correct":true},{"label":"$3$","why":"$3y$ 從右邊移到左邊要變號：$y'-3y=x$。"},{"label":"$x$","why":"$x$ 不含 $y$，是 $Q$，不是 $P$。"}]},{"ask":"$y'+5y=10$，$x\\to\\infty$ 時每一條解都趨近？","options":[{"label":"$2$","correct":true},{"label":"$10$","why":"平衡值是讓 $5y=10$ 的 $y$，也就是 $\\frac{b}{a}=2$，不是 $b$。"},{"label":"$\\infty$","why":"通解 $2+Ce^{-5x}$，$a=5>0$，指數項衰減到 $0$。"}]},{"ask":"$y_p$ 是一階線性方程的一個特解，$y_h=Ce^{-\\int P\\,dx}$ 是齊次通解。全部的解是？","options":[{"label":"$y_p+y_h$","correct":true},{"label":"$y_p\\cdot y_h$","why":"線性方程的解是相加組合：任兩個解的差才是齊次解。"},{"label":"只有 $y_p$","why":"$y_p$ 沒有任意常數，配不上一般的初始條件。"}]}],"practice":[{"id":"gap-der-ode-001","core":true},{"id":"cx-ode-005","core":true},{"id":"ode-lin-003","core":true},{"id":"ode-lin-005","core":true},{"id":"ode-lin-007","core":true,"note":"猜 $y=2x+1$ 是特解，代初始條件後 $C=0$。"},{"id":"ap-gro-005"}]},"integrating-factor":{"id":"integrating-factor","prerequisites":["first-order-linear","product-rule","integration-by-parts"],"next":["exact-equations"],"related":["ibp-cyclic"],"objectives":["從乘法法則推出積分因子 $\\mu=e^{\\int P\\,dx}$，說得出它為什麼能讓左邊變成 $(\\mu y)'$。","照四個步驟解任何一階線性方程，常數 $C$ 放在正確的位置。","處理 $P=\\frac{1}{x}$ 這類讓 $\\mu$ 變成 $x$ 的情形，並用初始條件定常數。"],"concept":[{"heading":"① 想法：把左邊變成一個乘積的導數","body":["$y'+P(x)y=Q(x)$ 的左邊有 $y'$ 也有 $y$，沒辦法直接積分。但乘法法則說 $(\\mu y)'=\\mu y'+\\mu'y$，長得很像。","把方程兩邊乘一個待定的函數 $\\mu(x)$：$\\mu y'+\\mu Py=\\mu Q$。左邊要等於 $(\\mu y)'=\\mu y'+\\mu'y$，只需要 $\\mu'=P\\mu$。這本身是可分離方程，一個解是 $\\mu=e^{\\int P\\,dx}$。"],"tex":["\\mu(x)=e^{\\int P(x)\\,dx},\\qquad (\\mu y)'=\\mu Q"]},{"heading":"② 四個步驟","body":["1. 化成標準形 $y'+P(x)y=Q(x)$，讀出 $P$（注意正負號）。","2. 算 $\\mu=e^{\\int P\\,dx}$。這裡取任何一個反導函數就好，不用加常數：加了常數只是讓 $\\mu$ 乘上一個倍數，兩邊一起乘，結果不變。","3. 兩邊乘 $\\mu$，左邊寫成 $(\\mu y)'$，得 $(\\mu y)'=\\mu Q$。","4. 積分：$\\mu y=\\int\\mu Q\\,dx+C$，再除以 $\\mu$。$C$ 要在除以 $\\mu$ 之前加上去，所以它最後會變成 $\\frac{C}{\\mu}$，不是單獨一個 $C$。"]},{"heading":"③ $\\int P\\,dx$ 是對數的時候","body":["$P=\\frac{1}{x}$ 時 $\\int P\\,dx=\\ln|x|$，$\\mu=e^{\\ln|x|}=|x|$。題目通常限定 $x>0$，$\\mu$ 就是 $x$；$P=\\frac{2}{x}$ 時 $\\mu=x^2$。","這時「乘 $\\mu$」的效果很直觀：$x\\left(y'+\\frac{y}{x}\\right)=xy'+y=(xy)'$，正是乘法法則。"]},{"heading":"④ 做完一定能檢查","body":["把答案代回原方程：算 $y'$，加上 $P(x)y$，看是不是等於 $Q(x)$；再看初始條件。這一步也順便抓出最常見的錯：$\\mu$ 的指數正負號弄反（用了 $e^{-\\int P\\,dx}$）時，算出來的 $y$ 代回去會得到 $y'+P(x)y=Q(x)+2P(x)y$，多出一項，馬上看得出來。"]},{"heading":"為什麼這樣得到的是全部的解","body":["在 $P$、$Q$ 連續的區間上，$\\mu=e^{\\int P\\,dx}>0$ 而且可微。任何解 $y$ 都滿足 $(\\mu y)'=\\mu Q$，所以 $\\mu y$ 是 $\\mu Q$ 的反導函數，只能是 $\\int\\mu Q\\,dx+C$ 的樣子。反過來，這個公式代回去也確實是解。所以公式 $y=\\frac{\\int\\mu Q\\,dx+C}{\\mu}$ 恰好給出所有解，而且解在整個區間上都存在，不會像 $y'=y^2$ 那樣爆破。"],"collapsible":true}],"workedExamples":[{"title":"基本型","prompt":"$y'+y=x$，$y(0)=1$。","problemId":"ode-lin-001","steps":["$P=1$，$\\mu=e^x$。","兩邊乘 $e^x$：$(e^xy)'=xe^x$。","分部積分：$\\int xe^x\\,dx=(x-1)e^x+C$，所以 $e^xy=(x-1)e^x+C$。","除以 $e^x$：$y=x-1+Ce^{-x}$。","代 $y(0)=1$：$-1+C=1$，$C=2$。$y=x-1+2e^{-x}$。"],"answer":"$y=x-1+2e^{-x}$"},{"title":"$P$ 是負的","prompt":"$y'-y=e^x$，$y(0)=0$。","problemId":"ode-lin-002","steps":["$P=-1$，$\\mu=e^{-x}$（不是 $e^x$）。","$(e^{-x}y)'=e^{-x}\\cdot e^x=1$。","積分：$e^{-x}y=x+C$，$y=(x+C)e^x$。","代 $y(0)=0$：$C=0$，$y=xe^x$。"],"answer":"$y=xe^x$","note":"第一個驗算就是 $y'=y+e^x$。"},{"title":"$\\mu=x$","prompt":"$y'+\\frac{y}{x}=\\frac{1}{x^2}$，$y(1)=0$（$x>0$）。","problemId":"ode-lin-006","steps":["$P=\\frac{1}{x}$，$\\int P\\,dx=\\ln x$（$x>0$），$\\mu=x$。","$(xy)'=x\\cdot\\frac{1}{x^2}=\\frac{1}{x}$。","積分：$xy=\\ln x+C$。","代 $x=1$、$y=0$：$0=0+C$，$C=0$。","$y=\\frac{\\ln x}{x}$。"],"answer":"$y=\\frac{\\ln x}{x}$"}],"pitfalls":["$\\mu=e^{\\int P\\,dx}$ 的 $P$ 正負號讀錯（$y'-y$ 的 $P$ 是 $-1$）。","除以 $\\mu$ 時只除了 $\\int\\mu Q\\,dx$，$C$ 沒除：$e^{2x}y=e^x+C$ 應得 $y=e^{-x}+Ce^{-2x}$。","把 $\\mu$ 寫成 $\\int P\\,dx$ 本身，忘了取指數。","還沒化成標準形就讀 $P$：$xy'+2y=\\dots$ 要先除以 $x$。"],"checks":[{"ask":"$y'+3y=e^x$ 的積分因子是？","options":[{"label":"$e^{3x}$","correct":true},{"label":"$e^{-3x}$","why":"$\\mu$ 要滿足 $\\mu'=P\\mu$，$P=3$，所以 $\\mu=e^{+3x}$；$e^{-3x}$ 是齊次解，不是積分因子。"},{"label":"$e^x$","why":"$e^x$ 是右邊的 $Q$；積分因子只看 $P$。"}]},{"ask":"$y'+\\frac{2}{x}y=1$（$x>0$）的積分因子是？","options":[{"label":"$x^2$","correct":true},{"label":"$e^{2/x}$","why":"要先積分 $P$：$\\int\\frac{2}{x}\\,dx=2\\ln x$，不是直接把 $\\frac{2}{x}$ 放進指數。"},{"label":"$2\\ln x$","why":"這是 $\\int P\\,dx$，還要取指數：$e^{2\\ln x}=x^2$。"}]},{"ask":"標準形乘上 $\\mu=e^{\\int P\\,dx}$ 之後，左邊 $\\mu y'+\\mu Py$ 等於？","options":[{"label":"$(\\mu y)'$","correct":true},{"label":"$\\mu'y'$","why":"乘法法則給的是和 $\\mu y'+\\mu'y$，不是導數的乘積。"},{"label":"$(\\mu'y)'$","why":"要湊的是 $\\mu$ 和 $y$ 的乘積的導數；$\\mu'=P\\mu$ 正是為了讓 $\\mu Py$ 變成 $\\mu'y$。"}]},{"ask":"已得到 $e^{2x}y=e^x+C$，$y$ 是？","options":[{"label":"$e^{-x}+Ce^{-2x}$","correct":true},{"label":"$e^{-x}+C$","why":"$C$ 也要除以 $e^{2x}$；把 $C$ 留在外面，代初始條件會得到錯的解。"},{"label":"$e^{-x}$","why":"常數 $C$ 不能丟，要等初始條件來定。"}]}],"practice":[{"id":"gap-der-ode-003","core":true},{"id":"ode-lin-001","core":true},{"id":"ode-lin-002","core":true},{"id":"ode-lin-006","core":true},{"id":"ode-val-003","core":true},{"id":"ode-lin-004"},{"id":"ode-lin-008","note":"$\\int e^x\\sin x\\,dx$ 要用〈重複分部與循環積分〉。"},{"id":"ap-mix-002","challenge":true,"note":"挑戰：先自己列方程 $S'=2-\\frac{S}{25}$。"}]},"exact-equations":{"id":"exact-equations","prerequisites":["integrating-factor","partial-derivatives","clairaut","implicit-differentiation"],"next":["second-order-linear"],"related":["conservative-fields","potential-function","first-order-linear","separation-of-variables"],"objectives":["把 $M\\,dx+N\\,dy=0$ 讀成「某個 $F(x,y)$ 的等高線」，說出解寫成 $F(x,y)=C$ 的理由。","用 $\\frac{\\partial M}{\\partial y}=\\frac{\\partial N}{\\partial x}$ 判斷是否正合，並知道這個判準需要什麼條件。","用「先對 $x$ 積分、再配 $y$」找出 $F$。"],"concept":[{"heading":"① 從等高線倒推回方程（本課選修）","body":["如果 $y(x)$ 讓 $F(x,y(x))=C$ 一直成立，對 $x$ 微分（〈隱函數微分〉）：$F_x+F_y\\cdot y'=0$，也就是 $F_x\\,dx+F_y\\,dy=0$。","倒過來看：一個寫成 $M\\,dx+N\\,dy=0$ 的方程，如果剛好有 $F$ 使 $M=F_x$、$N=F_y$，它就叫正合，解就是 $F(x,y)=C$ 這一族等高線。解法變成「找 $F$」。"]},{"heading":"② 怎麼知道 $F$ 存在：比對交叉偏導","body":["若 $M=F_x$、$N=F_y$，而且 $F$ 的二階偏導連續，〈Clairaut 定理〉給 $M_y=F_{xy}=F_{yx}=N_x$。所以正合的必要條件是 $\\frac{\\partial M}{\\partial y}=\\frac{\\partial N}{\\partial x}$。","反過來也成立，但要條件：$M$、$N$ 與它們的一階偏導在一個矩形（更一般地，沒有破洞的區域）上連續，且 $M_y=N_x$，那 $F$ 就存在。"]},{"heading":"③ 找 $F$：先對 $x$ 積分，再配 $y$","body":["1. $F=\\int M\\,dx$，對 $x$ 積分時把 $y$ 當常數，所以「積分常數」可以是 $y$ 的任意函數 $g(y)$。","2. 對 $y$ 偏微分，令它等於 $N$，解出 $g'(y)$。$g'(y)$ 一定只含 $y$；若出現 $x$，代表前面算錯了，或方程根本不正合。","3. 積出 $g(y)$，答案寫成 $F(x,y)=C$，有初始條件就代進去定 $C$。"]},{"heading":"④ 一階方程，先問三個問題","body":["能寫成 $g(x)h(y)$ 嗎？能就〈分離變數〉。能整理成 $y'+P(x)y=Q(x)$ 嗎？能就用〈積分因子〉。寫成 $M\\,dx+N\\,dy=0$ 之後 $M_y=N_x$ 嗎？是就找 $F$。三種都不是，這門課的工具就不夠了。"]},{"heading":"為什麼要「沒有破洞」","body":["$M=-\\frac{y}{x^2+y^2}$、$N=\\frac{x}{x^2+y^2}$ 在去掉原點的平面上處處滿足 $M_y=N_x=\\frac{y^2-x^2}{(x^2+y^2)^2}$。但沒有一個在整個去掉原點的平面上都可微的 $F$：局部上 $F$ 就是極角 $\\theta$，繞原點一圈會多出 $2\\pi$，接不回來。限制在一個不含原點的矩形裡，$F$ 就存在。這和〈保守場〉與〈位勢函數〉是同一件事。","不正合的方程有時乘上一個因子就變成正合；〈一階線性〉方程乘上積分因子 $\\mu$ 之後就是正合的。"],"collapsible":true}],"workedExamples":[{"title":"判斷、找 $F$、寫解","prompt":"$(2xy+3)\\,dx+(x^2-1)\\,dy=0$","steps":["$M=2xy+3$，$N=x^2-1$。$M_y=2x$，$N_x=2x$，相等，正合（$M$、$N$ 是多項式，處處連續）。","對 $x$ 積分 $M$：$F=x^2y+3x+g(y)$。","對 $y$ 偏微分：$F_y=x^2+g'(y)$，令它等於 $N=x^2-1$，得 $g'(y)=-1$，$g(y)=-y$。","解：$x^2y+3x-y=C$。","需要的話可以解出 $y=\\frac{C-3x}{x^2-1}$（$x\\ne\\pm1$）。"],"answer":"$x^2y+3x-y=C$","note":"第三條驗算取 $C=5$，把解出的 $y(x)$ 代回 $M+N\\,y'=0$。"},{"title":"線性方程也可以是正合","prompt":"$xy'+y=x^2$，$y(1)=1$（$x>0$）。","problemId":"ode-lin-004","steps":["寫成 $(y-x^2)\\,dx+x\\,dy=0$：$M=y-x^2$，$N=x$。","$M_y=1$，$N_x=1$，正合。","$F=\\int(y-x^2)\\,dx=xy-\\frac{x^3}{3}+g(y)$。$F_y=x+g'(y)=x$，所以 $g'=0$，$g$ 是常數。","解：$xy-\\frac{x^3}{3}=C$。代 $(1,1)$：$1-\\frac{1}{3}=\\frac{2}{3}$。","$xy=\\frac{x^3}{3}+\\frac{2}{3}$，$y=\\frac{x^3+2}{3x}$，和用積分因子算的一樣。"],"answer":"$y=\\frac{x^3+2}{3x}$"},{"title":"含指數與三角","prompt":"$(e^x\\sin y+2x)\\,dx+e^x\\cos y\\,dy=0$，$y(0)=\\frac{\\pi}{2}$。","steps":["$M_y=e^x\\cos y$，$N_x=e^x\\cos y$，正合。","$F=\\int(e^x\\sin y+2x)\\,dx=e^x\\sin y+x^2+g(y)$。","$F_y=e^x\\cos y+g'(y)=e^x\\cos y$，$g'=0$。","$F=e^x\\sin y+x^2$。代 $\\left(0,\\frac{\\pi}{2}\\right)$：$1\\cdot1+0=1$。","解：$e^x\\sin y+x^2=1$。"],"answer":"$e^x\\sin y+x^2=1$"}],"pitfalls":["比錯偏導：要比 $M_y$ 和 $N_x$，不是 $M_x$ 和 $N_y$。","對 $x$ 積分後只加常數 $C$，忘了它可以是 $g(y)$。","把 $g(y)$ 加進答案時又多加了一次重複的項（例如 $x^2$ 算兩次）。","答案寫成 $F(x,y)=0$：解是一整族等高線 $F=C$。"],"checks":[{"ask":"$(3x^2+y)\\,dx+(x+2y)\\,dy=0$ 是正合方程嗎？","options":[{"label":"是，$M_y=1=N_x$","correct":true},{"label":"不是，因為 $M$ 含 $x^2$","why":"判準是交叉偏導相等，$x^2$ 對 $y$ 偏微分是 $0$，不影響。"},{"label":"要先解出來才知道","why":"正合的判斷不用解：直接比 $\\frac{\\partial M}{\\partial y}$ 與 $\\frac{\\partial N}{\\partial x}$。"}]},{"ask":"$y\\,dx+2x\\,dy=0$ 是正合方程嗎？","options":[{"label":"不是，$M_y=1$、$N_x=2$","correct":true},{"label":"是，因為 $M$、$N$ 都是一次式","why":"一次式不保證正合，要看交叉偏導是否相等。"},{"label":"是，因為 $M_x=N_y=0$","why":"比錯了偏導：要比 $M$ 對 $y$、$N$ 對 $x$。"}]},{"ask":"$F=\\int M\\,dx$ 時加上的「積分常數」應該是？","options":[{"label":"$y$ 的任意函數 $g(y)$","correct":true},{"label":"一個數 $C$","why":"對 $x$ 積分時 $y$ 被當成常數，所以任何只含 $y$ 的式子對 $x$ 偏微分都是 $0$。"},{"label":"$x$ 的任意函數 $g(x)$","why":"$g(x)$ 對 $x$ 偏微分不是 $0$，會改變 $F_x=M$。"}]},{"ask":"正合方程 $M\\,dx+N\\,dy=0$ 的解怎麼寫？","options":[{"label":"$F(x,y)=C$","correct":true},{"label":"$F(x,y)=0$","why":"那只是其中一條等高線；每一個 $C$ 都給一條解。"},{"label":"$y=F(x,y)$","why":"$F$ 是位勢函數，解是它的等高線，不是 $y$ 等於它。"}]}],"practice":[{"id":"ode-lin-004","core":true,"note":"寫成 $(y-x^2)\\,dx+x\\,dy=0$，或直接看出左邊是 $(xy)'$。"}]},"second-order-linear":{"id":"second-order-linear","prerequisites":["first-order-linear","initial-value-problem","higher-derivatives"],"next":["characteristic-equation"],"related":["undetermined-coefficients","harmonic-oscillator"],"objectives":["說出齊次二階線性方程的疊加原理，並知道它對非齊次、非線性方程不成立。","用 Wronskian 判斷兩個解是否線性獨立，說出通解為什麼需要兩個獨立的解。","寫出通解 $y=c_1y_1+c_2y_2$（非齊次再加 $y_p$），用 $y(x_0)$、$y'(x_0)$ 定出 $c_1$、$c_2$。"],"concept":[{"heading":"① 形式與物理來源","body":["二階線性方程：$y''+p(x)y'+q(x)y=g(x)$。$g=0$ 叫齊次。牛頓定律 $F=ma$ 中加速度是位置的二階導數，所以彈簧、電路這類系統都是二階方程（〈簡諧振盪〉）。","物理上要知道起始位置和起始速度，運動才確定。數學上對應兩個初始條件 $y(x_0)$、$y'(x_0)$。"]},{"heading":"② 疊加：齊次方程的解可以線性組合","body":["記 $L[y]=y''+py'+qy$。微分是線性的，所以 $L[c_1y_1+c_2y_2]=c_1L[y_1]+c_2L[y_2]$。若 $y_1$、$y_2$ 都是齊次方程 $L[y]=0$ 的解，$c_1y_1+c_2y_2$ 也是。","對非齊次不成立：$L[y_1]=g$、$L[y_2]=g$，相加得 $2g$。對非線性方程也不成立。"]},{"heading":"③ 要兩個「真的不同」的解","body":["$y''+y=0$ 有解 $\\cos x$ 和 $2\\cos x$，但 $c_1\\cos x+c_2\\cdot2\\cos x$ 其實只是 $(c_1+2c_2)\\cos x$，只有一個自由度，在 $x=0$ 的導數永遠是 $0$，配不出 $y'(0)=1$。","兩個解不成比例，叫線性獨立。檢查的工具是 Wronskian $W=y_1y_2'-y_1'y_2$。結論：在 $p$、$q$ 連續的區間上，若 $y_1$、$y_2$ 是齊次方程的解且 $W$ 不為 $0$，則 $c_1y_1+c_2y_2$ 就是全部的解。"],"tex":["W(y_1,y_2)=\\det\\begin{pmatrix}y_1 & y_2\\\\ y_1' & y_2'\\end{pmatrix}=y_1y_2'-y_1'y_2"]},{"heading":"④ 非齊次：一樣是齊次通解加特解","body":["兩個非齊次的解相減，$L[y-y_p]=g-g=0$，差是齊次解。所以 $y=y_p+c_1y_1+c_2y_2$。這和〈一階線性〉的結構一模一樣。怎麼找 $y_p$ 在〈待定係數〉。"]},{"heading":"為什麼 $W\\ne 0$ 就夠：兩個條件解兩個常數","body":["要配 $y(x_0)=a$、$y'(x_0)=b$，得解 $c_1y_1(x_0)+c_2y_2(x_0)=a$、$c_1y_1'(x_0)+c_2y_2'(x_0)=b$。這個 $2\\times2$ 線性方程組的係數行列式正是 $W(x_0)$。$W(x_0)\\ne 0$ 時對任何 $a$、$b$ 都恰有一組 $c_1$、$c_2$。","存在唯一定理：$p$、$q$、$g$ 在含 $x_0$ 的區間 $I$ 上連續，則對任何 $a$、$b$，初值問題在整個 $I$ 上恰有一個解。所以任何解都被它在 $x_0$ 的 $(y,y')$ 決定，也就一定等於某個 $c_1y_1+c_2y_2$。另外，兩個解的 $W$ 在 $I$ 上要嘛處處為 $0$、要嘛處處不為 $0$，只要檢查一點。"],"collapsible":true}],"workedExamples":[{"title":"兩個解、Wronskian、初始條件","prompt":"已知 $e^x$ 與 $e^{2x}$ 是 $y''-3y'+2y=0$ 的解。求 $y(0)=0$、$y'(0)=1$ 的解。","problemId":"ode-h2-001","steps":["$W=e^x\\cdot2e^{2x}-e^x\\cdot e^{2x}=e^{3x}$，永遠不為 $0$，所以 $y=c_1e^x+c_2e^{2x}$ 是通解。","$y(0)=0$：$c_1+c_2=0$。","$y'=c_1e^x+2c_2e^{2x}$，$y'(0)=1$：$c_1+2c_2=1$。","相減得 $c_2=1$，$c_1=-1$。","$y=e^{2x}-e^x$。"],"answer":"$y=e^{2x}-e^x$"},{"title":"$\\cos$ 與 $\\sin$","prompt":"$y''+y=0$，$y(0)=1$、$y'(0)=0$。","problemId":"ode-h2-002","steps":["$\\cos x$、$\\sin x$ 都是解：$(\\cos x)''=-\\cos x$、$(\\sin x)''=-\\sin x$。","$W=\\cos x\\cdot\\cos x-(-\\sin x)\\cdot\\sin x=\\cos^2x+\\sin^2x=1\\ne 0$，通解 $y=c_1\\cos x+c_2\\sin x$。","$y(0)=c_1=1$；$y'(0)=c_2=0$。","$y=\\cos x$。"],"answer":"$y=\\cos x$"},{"title":"非齊次：特解加齊次通解","prompt":"$y''+y=x$，$y(0)=0$、$y'(0)=0$。","problemId":"ode-p2-001","steps":["猜特解 $y_p=x$：$y_p''+y_p=0+x=x$。✔","通解 $y=x+c_1\\cos x+c_2\\sin x$。","$y(0)=c_1=0$。","$y'=1-c_1\\sin x+c_2\\cos x$，$y'(0)=1+c_2=0$，$c_2=-1$。","$y=x-\\sin x$。注意常數要在加上 $y_p$ 之後才定，不能先定齊次部分。"],"answer":"$y=x-\\sin x$"}],"pitfalls":["拿兩個成比例的解（$\\cos x$ 與 $2\\cos x$）組通解。","對非齊次方程用疊加：兩個非齊次解相加不再是解。","先用初始條件定齊次部分的常數，再加上 $y_p$：常數要在 $y=y_p+c_1y_1+c_2y_2$ 整個寫好之後才定。","二階方程只給一個條件就想定出唯一解。"],"checks":[{"ask":"$y_1$、$y_2$ 都是 $y''+4y=0$ 的解，下列哪一個也一定是解？","options":[{"label":"$3y_1-5y_2$","correct":true},{"label":"$y_1y_2$","why":"疊加只保證線性組合；乘積的二階導數會多出 $2y_1'y_2'$ 這種交叉項。"},{"label":"$y_1+1$","why":"常數 $1$ 不是解：$1''+4\\cdot1=4\\ne 0$，加上去就壞了。"}]},{"ask":"為什麼 $c_1\\cos x+c_2\\cdot2\\cos x$ 不是 $y''+y=0$ 的通解？","options":[{"label":"兩者成比例（$W=0$），在 $x=0$ 的導數永遠是 $0$，配不出 $y'(0)=1$","correct":true},{"label":"因為 $2\\cos x$ 不是解","why":"它是解：$(2\\cos x)''=-2\\cos x$。問題是它和 $\\cos x$ 成比例。"},{"label":"因為通解只需要一個解","why":"二階方程有兩個初始條件，要兩個獨立的解才配得起來。"}]},{"ask":"$W(e^x,xe^x)$ 是？","options":[{"label":"$e^{2x}$","correct":true},{"label":"$0$","why":"兩個都有 $e^x$，但 $\\frac{xe^x}{e^x}=x$ 不是常數，它們不成比例：$e^x(e^x+xe^x)-e^x\\cdot xe^x=e^{2x}$。"},{"label":"$xe^{2x}$","why":"$xe^{2x}$ 那兩項正好相消：$e^x\\cdot xe^x-e^x\\cdot xe^x=0$，只剩 $e^{2x}$。"}]},{"ask":"二階線性初值問題要給哪兩個條件才保證唯一解？","options":[{"label":"同一點的 $y(x_0)$ 與 $y'(x_0)$","correct":true},{"label":"兩個不同點的 $y(x_0)$ 與 $y(x_1)$","why":"那是邊界值問題，可能無解或無限多解：$y''+y=0$、$y(0)=0$、$y(\\pi)=0$ 有無限多個解 $c\\sin x$。"},{"label":"只要 $y(x_0)$","why":"兩個常數 $c_1$、$c_2$ 要兩個條件。"}]}],"practice":[{"id":"der-061","core":true},{"id":"der-059","core":true},{"id":"der-064","core":true},{"id":"ode-h2-002","core":true},{"id":"gap-der-ode-004","core":true},{"id":"der-062"},{"id":"der-065"},{"id":"ode-p2-001","challenge":true,"note":"挑戰：猜一個特解，再加上齊次通解定常數。"}]},"characteristic-equation":{"id":"characteristic-equation","prerequisites":["second-order-linear","derivative-exp"],"next":["distinct-real-roots"],"related":["repeated-roots","complex-roots"],"objectives":["說得出為什麼常數係數方程要猜 $y=e^{rx}$，並從 $ay''+by'+cy=0$ 寫出特徵方程 $ar^2+br+c=0$。","解出特徵根，並驗證對應的 $e^{rx}$ 真的是解。","用判別式 $b^2-4ac$ 分成三種情況，知道各自接下來要學什麼。"],"concept":[{"heading":"① 為什麼猜 $e^{rx}$","body":["常數係數齊次方程 $ay''+by'+cy=0$（$a\\ne 0$）要求 $y$、$y'$、$y''$ 乘上常數後加起來互相抵消。要能抵消，三者最好長得一樣，只差倍數。$e^{rx}$ 正好如此：$(e^{rx})'=re^{rx}$，$(e^{rx})''=r^2e^{rx}$。","這是猜測，不是推導；猜完要代進去檢查，下面就是檢查。"]},{"heading":"② 代進去：得到一個二次方程","body":["代 $y=e^{rx}$：$ar^2e^{rx}+bre^{rx}+ce^{rx}=(ar^2+br+c)e^{rx}$。$e^{rx}$ 永遠不是 $0$，所以 $e^{rx}$ 是解，若且唯若 $ar^2+br+c=0$。這個二次方程叫特徵方程，它的根叫特徵根。","讀法：$y''$ 換成 $r^2$，$y'$ 換成 $r$，$y$ 換成 $1$，係數照抄。缺項就是係數 $0$：$y''-4y=0$ 的特徵方程是 $r^2-4=0$；$y''+3y'=0$ 的是 $r^2+3r=0$，根 $r=0$ 對應常數解 $y=1$。"],"tex":["ay''+by'+cy=0\\quad\\longrightarrow\\quad ar^2+br+c=0"]},{"heading":"③ 判別式分三種情況","body":["$b^2-4ac>0$：兩個相異實根 $r_1$、$r_2$，得到兩個獨立的解 $e^{r_1x}$、$e^{r_2x}$（〈相異實根〉）。","$b^2-4ac=0$：只有一個根 $r$，只得到一個解 $e^{rx}$，第二個要另外找，答案是 $xe^{rx}$（〈重根〉）。","$b^2-4ac<0$：根是複數 $\\alpha\\pm i\\beta$，實數解是 $e^{\\alpha x}\\cos\\beta x$、$e^{\\alpha x}\\sin\\beta x$，曲線會振盪（〈複數根〉）。","不論哪一種，最後都是用兩個獨立的解組成通解 $c_1y_1+c_2y_2$，再用兩個初始條件定常數。"]},{"heading":"④ 只適用常數係數","body":["係數若含 $x$，例如 $xy''+y=0$，代 $e^{rx}$ 會得到 $(xr^2+1)e^{rx}$，括號裡跟 $x$ 有關，找不到一個固定的 $r$ 讓它對所有 $x$ 都是 $0$。"]}],"workedExamples":[{"title":"寫出特徵方程並驗證","prompt":"$y''-5y'+6y=0$，找出形如 $e^{rx}$ 的解。","steps":["特徵方程：$r^2-5r+6=0$。","因式分解 $(r-2)(r-3)=0$，$r=2$ 或 $3$。","驗證 $e^{2x}$：$4e^{2x}-10e^{2x}+6e^{2x}=0$。✔","驗證 $e^{3x}$：$9e^{3x}-15e^{3x}+6e^{3x}=0$。✔","判別式 $25-24=1>0$，屬於相異實根，通解 $c_1e^{2x}+c_2e^{3x}$。"],"answer":"$e^{2x}$ 與 $e^{3x}$"},{"title":"首項係數不是 $1$","prompt":"$2y''+y'-y=0$。","steps":["特徵方程：$2r^2+r-1=0$。","因式分解 $(2r-1)(r+1)=0$，$r=\\frac{1}{2}$ 或 $-1$。","對應的解 $e^{x/2}$、$e^{-x}$。","判別式 $1+8=9>0$。"],"answer":"$e^{x/2}$ 與 $e^{-x}$"},{"title":"判別式是負的（預告）","prompt":"$y''+2y'+5y=0$ 屬於哪一種情況？","steps":["特徵方程 $r^2+2r+5=0$，判別式 $4-20=-16<0$。","公式解 $r=\\frac{-2\\pm\\sqrt{-16}}{2}=-1\\pm2i$，$\\alpha=-1$、$\\beta=2$。","依〈複數根〉，實數解是 $e^{-x}\\cos 2x$ 與 $e^{-x}\\sin 2x$：振盪，振幅以 $e^{-x}$ 衰減。這裡先代進去驗算，推導留到那一課。"],"answer":"複數根 $-1\\pm2i$；解 $e^{-x}\\cos 2x$、$e^{-x}\\sin 2x$"}],"pitfalls":["把 $y$ 換成 $r$ 而不是 $1$：$y''+4y'-5y=0$ 的常數項是 $-5$，不是 $-5r$。","缺項時亂補：$y''-9y=0$ 沒有 $r$ 項，特徵方程是 $r^2-9=0$。","$r^2=9$ 只取 $r=3$，漏了 $-3$。","把特徵方程用在變係數方程上。"],"checks":[{"ask":"$y''+4y'-5y=0$ 的特徵方程是？","options":[{"label":"$r^2+4r-5=0$","correct":true},{"label":"$r^2-5=0$","why":"$y'$ 對應 $r$，$4y'$ 要寫成 $4r$，不能丟掉。"},{"label":"$4r-5=0$","why":"$y''$ 對應 $r^2$，這一項不能丟；特徵方程是二次的。"}]},{"ask":"$y''-9y=0$ 的特徵根是？","options":[{"label":"$r=\\pm3$","correct":true},{"label":"$r=9$","why":"$r^2=9$，還要開根號，而且有正負兩個。"},{"label":"$r=\\pm3i$","why":"$r^2=+9$，不是 $-9$；$\\pm3i$ 是 $y''+9y=0$ 的根。"}]},{"ask":"$y''+6y'+9y=0$ 屬於哪一種情況？","options":[{"label":"重根 $r=-3$","correct":true},{"label":"相異實根","why":"判別式 $36-36=0$，兩根重合，只有 $-3$。"},{"label":"複數根","why":"判別式是 $0$ 不是負的，根是實數。"}]},{"ask":"為什麼特徵方程只能用在常數係數方程？","options":[{"label":"係數含 $x$ 時，代入 $e^{rx}$ 得到的括號會隨 $x$ 變，找不到固定的 $r$","correct":true},{"label":"因為 $e^{rx}$ 不能微分兩次","why":"$e^{rx}$ 可以無限次微分；問題出在係數。"},{"label":"因為變係數方程沒有解","why":"變係數方程通常有解（存在唯一定理），只是解不是 $e^{rx}$ 的樣子。"}]}],"practice":[{"id":"ode-h2-001","core":true},{"id":"ode-h2-006","core":true},{"id":"ode-h2-007","note":"預告：根是 $\\pm3i$，解是 $\\sin$、$\\cos$。"},{"id":"ode-h2-004","note":"預告：重根，第二個解是 $xe^{rx}$。"}]},"distinct-real-roots":{"id":"distinct-real-roots","prerequisites":["characteristic-equation","second-order-linear"],"next":["repeated-roots"],"related":["complex-roots"],"objectives":["特徵方程有兩個相異實根 $r_1$、$r_2$ 時，寫出通解 $y=C_1e^{r_1x}+C_2e^{r_2x}$。","用 $y(0)$、$y'(0)$ 兩個初始條件解出 $C_1$、$C_2$。","看通解說出 $x\\to\\infty$ 時的行為：哪一個指數會贏。"],"concept":[{"heading":"① 從特徵方程到兩個解","body":["常係數齊次方程 $ay''+by'+cy=0$。試 $y=e^{rx}$：$y'=re^{rx}$、$y''=r^2e^{rx}$，代入得 $(ar^2+br+c)e^{rx}=0$。$e^{rx}$ 永遠不是 $0$，所以 $r$ 必須是特徵方程 $ar^2+br+c=0$ 的根（〈特徵方程〉）。","判別式 $b^2-4ac>0$ 時有兩個不同的實根 $r_1\\ne r_2$，於是 $e^{r_1x}$ 與 $e^{r_2x}$ 都是解。"]},{"heading":"② 疊加：兩個解的組合還是解","body":["方程是線性、齊次的，所以兩個解的任意常數倍相加還是解（〈二階線性〉）。通解是："],"tex":["y = C_1 e^{r_1 x} + C_2 e^{r_2 x}"]},{"heading":"③ 為什麼這已經是「全部」的解","body":["二階方程要兩個初始條件 $y(0)=y_0$、$y'(0)=v_0$ 才確定一個解。把通解代進去：$C_1+C_2=y_0$、$r_1C_1+r_2C_2=v_0$。這組聯立方程的係數行列式是 $r_2-r_1\\ne 0$，所以不管 $y_0$、$v_0$ 是多少，$C_1$、$C_2$ 都解得出來。","再配上存在唯一性定理（每組初始條件恰好一個解，〈二階線性〉），任何一個解都等於通解裡的某一個。$r_1=r_2$ 時行列式是 $0$，這就是重根要另外處理的原因。"]},{"heading":"④ 圖形長什麼樣","body":["沒有振盪。$x\\to\\infty$ 時，根比較大的那一項主宰（只要它的係數不是 $0$）；兩根都是負的，解衰減到 $0$。","解最多穿過 $x$ 軸一次：$C_1e^{r_1x}+C_2e^{r_2x}=0$ 等價於 $e^{(r_1-r_2)x}=-\\frac{C_2}{C_1}$，左邊是嚴格單調的函數，最多一個解。"]}],"workedExamples":[{"title":"初值問題","prompt":"$y''-3y'+2y=0$，$y(0)=0$，$y'(0)=1$","problemId":"ode-h2-001","steps":["特徵方程 $r^2-3r+2=0$，即 $(r-1)(r-2)=0$，$r=1$、$2$。","通解 $y=C_1e^x+C_2e^{2x}$，所以 $y'=C_1e^x+2C_2e^{2x}$。","$y(0)=0$：$C_1+C_2=0$。$y'(0)=1$：$C_1+2C_2=1$。","相減得 $C_2=1$，$C_1=-1$。"],"answer":"$y=e^{2x}-e^x$"},{"title":"根是 $\\pm1$","prompt":"$y''-y=0$，$y(0)=2$，$y'(0)=0$","problemId":"ode-h2-006","steps":["特徵方程 $r^2-1=0$，$r=1$、$-1$。","通解 $y=C_1e^x+C_2e^{-x}$，$y'=C_1e^x-C_2e^{-x}$。","$y(0)=2$：$C_1+C_2=2$。$y'(0)=0$：$C_1-C_2=0$。","$C_1=C_2=1$。"],"answer":"$y=e^x+e^{-x}$（也就是 $2\\cosh x$）"},{"title":"首項係數不是 $1$","prompt":"求 $2y''+y'-y=0$ 的通解。","steps":["特徵方程 $2r^2+r-1=0$。因式分解 $(2r-1)(r+1)=0$。","$r=\\frac{1}{2}$ 或 $r=-1$。注意根是讓括號為 $0$ 的數，$(2r-1)$ 給的是 $\\frac{1}{2}$，不是 $2$。","通解 $y=C_1e^{x/2}+C_2e^{-x}$。"],"answer":"$y=C_1e^{x/2}+C_2e^{-x}$"}],"pitfalls":["根的正負號弄反：$(r+3)(r-2)=0$ 的根是 $-3$ 與 $2$。","漏掉 $r=0$ 的根：$y''-5y'=0$ 的通解有一個常數項 $C_1$（$e^{0x}=1$）。","只用 $y(0)$ 定常數，忘了先把通解微分再代 $y'(0)$。","寫成 $e^{r_1x}+e^{r_2x}$ 而沒有任意常數，那只是其中一個解，不是通解。"],"checks":[{"ask":"$y''+y'-6y=0$ 的通解是？","options":[{"label":"$y=C_1e^{2x}+C_2e^{-3x}$","correct":true},{"label":"$y=C_1e^{-2x}+C_2e^{3x}$","why":"$r^2+r-6=(r+3)(r-2)$，根是讓括號為 $0$ 的 $-3$ 與 $2$；你把括號裡的數直接當成根。"},{"label":"$y=e^{2x}+e^{-3x}$","why":"這只是一個特定的解。通解要有兩個任意常數，才能配上任意的初始條件。"}]},{"ask":"$y''-5y'=0$ 的通解是？","options":[{"label":"$y=C_1+C_2e^{5x}$","correct":true},{"label":"$y=Ce^{5x}$","why":"$r^2-5r=r(r-5)$ 還有 $r=0$ 這個根，$e^{0x}=1$，對應常數項 $C_1$。"},{"label":"$y=(C_1+C_2x)e^{5x}$","why":"那是重根的形式；這裡兩根 $0$ 與 $5$ 不相同。"}]},{"ask":"$y=C_1e^x+C_2e^{2x}$ 滿足 $y(0)=1$、$y'(0)=0$，則 $y={}$？","options":[{"label":"$2e^x-e^{2x}$","correct":true},{"label":"$e^x$","why":"$y(0)=1$ 對了，但 $y'(0)=1\\ne 0$。兩個條件都要用：$C_1+C_2=1$、$C_1+2C_2=0$。"},{"label":"$-e^x+2e^{2x}$","why":"$C_1$、$C_2$ 對調了：這個函數的 $y'(0)=-1+4=3$。"}]},{"ask":"$y=C_1e^{2x}+C_2e^{-3x}$，$C_1\\ne 0$。$x\\to\\infty$ 時 $y$ 怎樣？","options":[{"label":"像 $C_1e^{2x}$，往 $+\\infty$ 或 $-\\infty$ 跑","correct":true},{"label":"趨近 $0$","why":"只有 $e^{-3x}$ 那一項衰減；$e^{2x}$ 那一項係數不是 $0$，會主宰。"},{"label":"上下振盪","why":"實根只給指數，不給 $\\sin$、$\\cos$；振盪要等〈複數根〉。"}]}],"practice":[{"id":"ode-h2-006","core":true},{"id":"ode-h2-001","core":true},{"id":"cx-ode-006"}]},"repeated-roots":{"id":"repeated-roots","prerequisites":["distinct-real-roots","product-rule"],"next":["complex-roots"],"related":["characteristic-equation"],"objectives":["特徵方程有重根 $r$ 時，寫出通解 $y=(C_1+C_2x)e^{rx}$。","說得出為什麼只有 $e^{rx}$ 不夠，以及為什麼 $xe^{rx}$ 也是解。","用乘法法則對 $xe^{rx}$ 微分，正確代入初始條件。"],"concept":[{"heading":"① 只剩一個指數，少了一個常數","body":["$y''+4y'+4y=0$ 的特徵方程 $r^2+4r+4=(r+2)^2=0$，只有一個根 $r=-2$（重根，判別式 $b^2-4ac=0$）。","$e^{-2x}$ 是解，但 $C_1e^{-2x}+C_2e^{-2x}=(C_1+C_2)e^{-2x}$ 其實只有一個常數，配不上 $y(0)$、$y'(0)$ 兩個條件。需要第二個「不是 $e^{-2x}$ 常數倍」的解。"]},{"heading":"② 答案：再乘一個 $x$","body":["重根 $r$ 時，$xe^{rx}$ 也是解。通解是："],"tex":["y = (C_1 + C_2 x)\\,e^{rx}"]},{"heading":"③ $x$ 從哪裡來（直覺，不是證明）","body":["想像兩個根很接近：$r$ 與 $r+h$。那時 $e^{(r+h)x}$ 與 $e^{rx}$ 都是解，它們的差除以 $h$ 也是解（線性組合）。$h\\to0$ 時，$\\frac{e^{(r+h)x}-e^{rx}}{h}$ 趨近 $e^{rx}$ 對 $r$ 的導數，也就是 $xe^{rx}$。","這只是直覺：它假設「解的極限還是解」，而且方程本身也跟著 $h$ 在變。真正的證明是下面直接代入。"]},{"heading":"④ 直接驗證 $xe^{rx}$ 是解","body":["$y=xe^{rx}$，乘法法則：$y'=e^{rx}(1+rx)$，$y''=e^{rx}(2r+r^2x)$。","代入 $ay''+by'+cy$，整理成 $e^{rx}\\left[x(ar^2+br+c)+(2ar+b)\\right]$。","$r$ 是特徵方程的根，第一個括號是 $0$；重根 $r=-\\frac{b}{2a}$，所以 $2ar+b=0$。整個是 $0$。注意第二步只有重根才成立，相異根時 $xe^{rx}$ 不是解。"],"collapsible":true},{"heading":"⑤ 兩個解真的不同","body":["$\\frac{xe^{rx}}{e^{rx}}=x$ 不是常數，所以兩者不是彼此的常數倍。Wronskian：$W(e^{rx},xe^{rx})=e^{rx}\\cdot e^{rx}(1+rx)-re^{rx}\\cdot xe^{rx}=e^{2rx}$，永遠不是 $0$。$y(0)=C_1$、$y'(0)=rC_1+C_2$，任何初始條件都配得上。"]}],"workedExamples":[{"title":"常數剛好是 $0$ 的陷阱","prompt":"$y''+4y'+4y=0$，$y(0)=1$，$y'(0)=-2$","problemId":"ode-h2-004","steps":["$r^2+4r+4=(r+2)^2=0$，重根 $r=-2$。通解 $y=(C_1+C_2x)e^{-2x}$。","微分（乘法法則）：$y'=C_2e^{-2x}-2(C_1+C_2x)e^{-2x}$。","$y(0)=1$：$C_1=1$。$y'(0)=-2$：$C_2-2C_1=-2$，所以 $C_2=0$。","$C_2=0$ 不代表 $xe^{-2x}$ 那一項「不需要」，只是這組初始條件剛好用不到。"],"answer":"$y=e^{-2x}$"},{"title":"兩個常數都用上","prompt":"$y''-2y'+y=0$，$y(0)=1$，$y'(0)=0$","problemId":"ode-h2-003","steps":["$r^2-2r+1=(r-1)^2=0$，重根 $r=1$。通解 $y=(C_1+C_2x)e^x$。","$y'=C_2e^x+(C_1+C_2x)e^x$。","$y(0)=1$：$C_1=1$。$y'(0)=0$：$C_2+C_1=0$，$C_2=-1$。"],"answer":"$y=(1-x)e^x$"},{"title":"首項係數不是 $1$","prompt":"求 $4y''+4y'+y=0$ 的通解。","steps":["$4r^2+4r+1=(2r+1)^2=0$，重根 $r=-\\frac{1}{2}$。","通解 $y=(C_1+C_2x)e^{-x/2}$。"],"answer":"$y=(C_1+C_2x)e^{-x/2}$"}],"pitfalls":["寫成 $C_1e^{rx}+C_2e^{rx}$：其實只有一個常數。","對 $xe^{rx}$ 微分忘了乘法法則，把 $y'(0)$ 算成 $rC_2$。","把重根 $r=-2$ 寫成 $e^{2x}$：根的正負號要照 $(r+2)^2=0$ 解出來。","相異根也亂加 $x$：只有重根時 $xe^{rx}$ 才是解。"],"checks":[{"ask":"$y''-6y'+9y=0$ 的通解是？","options":[{"label":"$y=(C_1+C_2x)e^{3x}$","correct":true},{"label":"$y=C_1e^{3x}+C_2e^{3x}$","why":"兩項合起來是 $(C_1+C_2)e^{3x}$，只有一個常數，配不上兩個初始條件。"},{"label":"$y=C_1e^{3x}+C_2e^{-3x}$","why":"$(r-3)^2=0$ 的根只有 $3$，是重根；你把它當成 $r^2=9$ 的 $\\pm3$ 了。"}]},{"ask":"重根時為什麼需要 $xe^{rx}$？","options":[{"label":"只有 $e^{rx}$ 時，通解只有一個任意常數","correct":true},{"label":"因為 $e^{rx}$ 在重根時不是解","why":"$e^{rx}$ 照樣是解，只是不夠：少了第二個獨立的解。"},{"label":"因為重根的特徵方程沒有實根","why":"重根是實根（判別式 $=0$），只是兩個根重疊成一個。"}]},{"ask":"$y=(C_1+C_2x)e^{-2x}$，$y(0)=3$、$y'(0)=0$，則 $C_2={}$？","options":[{"label":"$6$","correct":true},{"label":"$0$","why":"你把 $C_2$ 當成 $y'(0)$。$y'(0)=C_2-2C_1$，$C_1=3$，所以 $C_2=6$。"},{"label":"$-6$","why":"$C_1e^{-2x}$ 微分貢獻的是 $-2C_1=-6$，移項後 $C_2=+6$。"}]},{"ask":"$y''+ky'+9y=0$（$k>0$）有重根時 $k={}$？","options":[{"label":"$6$","correct":true},{"label":"$3$","why":"判別式 $k^2-4\\cdot9=0$ 給 $k=6$；$3$ 是重根的大小（$r=-3$），不是 $k$。"},{"label":"$9$","why":"$9$ 是 $y$ 的係數；重根條件是 $k^2=36$。"}]}],"practice":[{"id":"ode-h2-004","core":true},{"id":"ode-h2-003","core":true},{"id":"der-064","note":"$W(e^x,xe^x)$ 不為 $0$：兩個解真的獨立。"}]},"complex-roots":{"id":"complex-roots","prerequisites":["repeated-roots","characteristic-equation"],"next":["undetermined-coefficients"],"related":["euler-formula","complex-numbers","harmonic-oscillator","damped-oscillator"],"objectives":["特徵方程的根是 $\\alpha\\pm i\\beta$（$\\beta>0$）時，寫出實數通解 $y=e^{\\alpha x}(C_1\\cos\\beta x+C_2\\sin\\beta x)$。","說得出為什麼複數解的實部與虛部各自是實數解。","從 $\\alpha$ 的正負與 $\\beta$ 的大小，看出解是衰減振盪、等幅振盪還是發散振盪。"],"concept":[{"heading":"① 判別式是負的時候","body":["$y''+2y'+5y=0$ 的特徵方程 $r^2+2r+5=0$，判別式 $4-20=-16<0$。公式解給 $r=\\frac{-2\\pm4i}{2}=-1\\pm2i$。","$e^{(-1+2i)x}$ 是解，但它是複數值的函數。我們要的是實數的解。"]},{"heading":"② Euler 公式把它拆開","body":["Euler 公式 $e^{i\\theta}=\\cos\\theta+i\\sin\\theta$（〈Euler 公式〉）。所以根 $r=\\alpha+i\\beta$ 給："],"tex":["e^{(\\alpha+i\\beta)x}=e^{\\alpha x}\\cos\\beta x + i\\,e^{\\alpha x}\\sin\\beta x"]},{"heading":"③ 實部、虛部各自是實數解","body":["方程的係數 $a$、$b$、$c$ 都是實數。把複數解寫成 $u+iv$，代入左邊得 $L[u]+iL[v]=0$，其中 $L[y]=ay''+by'+cy$。$L[u]$、$L[v]$ 都是實數，一個複數是 $0$ 必須實部虛部都是 $0$，所以 $L[u]=0$、$L[v]=0$。","於是 $e^{\\alpha x}\\cos\\beta x$ 與 $e^{\\alpha x}\\sin\\beta x$ 都是實數解，而且不是彼此的常數倍。通解："],"tex":["y = e^{\\alpha x}\\left(C_1\\cos\\beta x + C_2\\sin\\beta x\\right)"]},{"heading":"④ 另一個根 $\\alpha-i\\beta$ 呢","body":["它給的是 $e^{\\alpha x}\\cos\\beta x-i\\,e^{\\alpha x}\\sin\\beta x$，實部虛部跟上面一樣（差一個負號），沒有新東西。所以一對共軛根合起來給兩個實數解，正好是二階需要的數量。"]},{"heading":"⑤ 讀圖","body":["$\\beta$ 決定振盪多快（週期 $\\frac{2\\pi}{\\beta}$）；$e^{\\alpha x}$ 是包絡線：$\\alpha<0$ 振幅衰減，$\\alpha=0$ 等幅，$\\alpha>0$ 越振越大。這就是〈簡諧振盪〉與〈阻尼振盪〉的數學。"]}],"workedExamples":[{"title":"純虛根：等幅振盪","prompt":"$y''+9y=0$，$y(0)=0$，$y'(0)=3$","problemId":"ode-h2-007","steps":["$r^2+9=0$，$r=\\pm3i$：$\\alpha=0$、$\\beta=3$。","通解 $y=C_1\\cos 3x+C_2\\sin 3x$，$y'=-3C_1\\sin 3x+3C_2\\cos 3x$。","$y(0)=0$：$C_1=0$。$y'(0)=3$：$3C_2=3$，$C_2=1$。"],"answer":"$y=\\sin 3x$"},{"title":"衰減振盪","prompt":"$y''+2y'+5y=0$，$y(0)=1$，$y'(0)=-1$","problemId":"ode-h2-005","steps":["$r=-1\\pm2i$：$\\alpha=-1$、$\\beta=2$。通解 $y=e^{-x}(C_1\\cos 2x+C_2\\sin 2x)$。","$y(0)=1$：$C_1=1$。","$y'=-e^{-x}(C_1\\cos 2x+C_2\\sin 2x)+e^{-x}(-2C_1\\sin 2x+2C_2\\cos 2x)$，所以 $y'(0)=-C_1+2C_2$。","$y'(0)=-1$：$-1+2C_2=-1$，$C_2=0$。"],"answer":"$y=e^{-x}\\cos 2x$"},{"title":"$\\beta$ 帶根號","prompt":"求 $y''+y'+y=0$ 的通解。","steps":["$r^2+r+1=0$，$r=\\frac{-1\\pm\\sqrt{1-4}}{2}=-\\frac{1}{2}\\pm\\frac{\\sqrt3}{2}i$。","$\\alpha=-\\frac{1}{2}$、$\\beta=\\frac{\\sqrt3}{2}$。"],"answer":"$y=e^{-x/2}\\left(C_1\\cos\\frac{\\sqrt3x}{2}+C_2\\sin\\frac{\\sqrt3x}{2}\\right)$"}],"pitfalls":["$r^2+4=0$ 的根是 $\\pm2i$，$\\beta=2$，不是 $4$。","$\\alpha$、$\\beta$ 放反：根 $3\\pm2i$ 給 $e^{3x}(\\dots\\cos 2x\\dots)$，不是 $e^{2x}\\cos 3x$。","只留 $\\cos$ 那一項，丟掉 $\\sin$：通解要兩個常數。","忘了 $e^{\\alpha x}$，或對 $e^{\\alpha x}\\cos\\beta x$ 微分時漏掉乘法法則。","最後答案留著 $i$。實數方程、實數初始條件，答案一定是實數。"],"checks":[{"ask":"$y''+4y=0$ 的通解是？","options":[{"label":"$C_1\\cos 2x+C_2\\sin 2x$","correct":true},{"label":"$C_1e^{2x}+C_2e^{-2x}$","why":"那是 $y''-4y=0$（$r^2=4$）。這裡 $r^2=-4$，根是 $\\pm2i$。"},{"label":"$C_1\\cos 4x+C_2\\sin 4x$","why":"$r^2=-4$ 給 $r=\\pm2i$，$\\beta$ 是 $\\sqrt4=2$，不是 $4$。"}]},{"ask":"特徵方程的根是 $3\\pm2i$，通解是？","options":[{"label":"$e^{3x}(C_1\\cos 2x+C_2\\sin 2x)$","correct":true},{"label":"$e^{2x}(C_1\\cos 3x+C_2\\sin 3x)$","why":"實部虛部放反了：實部 $3$ 進指數，虛部 $2$ 是頻率。"},{"label":"$C_1e^{3x}+C_2e^{2x}$","why":"虛部不是另一個指數；$e^{2ix}$ 經 Euler 公式變成 $\\cos 2x$、$\\sin 2x$。"}]},{"ask":"為什麼 $e^{\\alpha x}\\cos\\beta x$ 與 $e^{\\alpha x}\\sin\\beta x$ 都是解？","options":[{"label":"方程係數是實數，複數解代入後實部、虛部要各自為 0","correct":true},{"label":"因為 $i$ 可以當成 $1$ 來算","why":"$i^2=-1$，不能當 $1$；理由是 $L[u]+iL[v]=0$ 推出 $L[u]=L[v]=0$。"},{"label":"只有實部是解，虛部是丟掉的部分","why":"虛部 $e^{\\alpha x}\\sin\\beta x$ 也是解，丟掉它通解就少一個常數。"}]},{"ask":"$y=e^{-x}(\\cos 2x+3\\sin 2x)$，$x\\to\\infty$ 時？","options":[{"label":"一邊振盪一邊衰減到 $0$","correct":true},{"label":"振幅越來越大","why":"$\\alpha=-1<0$，包絡線 $e^{-x}$ 在縮小。"},{"label":"不振盪，直接衰減","why":"$\\beta=2\\ne 0$，有 $\\cos 2x$、$\\sin 2x$，會一直穿過 $0$。"}]}],"practice":[{"id":"ode-h2-002","core":true},{"id":"ode-h2-007","core":true},{"id":"gap-der-ode-004"},{"id":"ode-h2-005","core":true},{"id":"ode-h2-008","challenge":true,"note":"挑戰：$\\alpha=2>0$，解一邊振盪一邊變大。"}]},"undetermined-coefficients":{"id":"undetermined-coefficients","prerequisites":["distinct-real-roots","repeated-roots","complex-roots"],"next":["variation-of-parameters"],"related":["driven-oscillator","resonance"],"objectives":["知道非齊次方程的通解是 $y=y_h+y_p$，並說得出為什麼。","右邊是多項式、指數、$\\sin/\\cos$ 時，寫出正確的猜測形式並解出係數。","猜測的某一項已經是齊次解時，會乘上 $x$（重根時乘 $x^2$）修正。"],"concept":[{"heading":"① 通解 $={}$ 齊次解 $+$ 一個特解","body":["$ay''+by'+cy=g(x)$，右邊 $g$ 不是 $0$。先解齊次方程（右邊換成 $0$）得 $y_h$，裡面有兩個常數；再找任何一個滿足原方程的函數 $y_p$（特解）。通解就是 $y=y_h+y_p$。","理由：若 $y$ 是任一個解，$y-y_p$ 代入左邊得 $g-g=0$，所以 $y-y_p$ 是齊次解，也就是 $y_h$ 的某一個。"]},{"heading":"② 猜一個跟右邊同家族的函數","body":["多項式、指數、$\\sin/\\cos$ 微分之後還是同一家族，所以照右邊的樣子猜，係數留成未知數，代入比對：","$g$ 是 $n$ 次多項式 $\\to$ 猜一般的 $n$ 次多項式（每一次方都要有）。","$g$ 是 $e^{kx}$ $\\to$ 猜 $Ae^{kx}$。","$g$ 是 $\\cos\\omega x$ 或 $\\sin\\omega x$ $\\to$ 猜 $A\\cos\\omega x+B\\sin\\omega x$。兩個都要，因為微分會把 $\\cos$ 變成 $\\sin$。","乘積照樣相乘，例如 $xe^x\\to(Ax+B)e^x$。"]},{"heading":"③ 修正規則：猜到齊次解就乘 $x$","body":["$y''+y'=1$：猜常數 $A$，代入得 $0=1$，失敗。原因是常數本身就是齊次解（$r=0$ 是特徵根），代進左邊一定是 $0$。","辦法：猜測裡和齊次解重複的部分乘上 $x$；如果那個根是重根，乘 $x^2$。乘完要確定已經不和齊次解重複。"]},{"heading":"④ 初始條件最後才用","body":["先寫出完整的 $y=y_h+y_p$，再代 $y(0)$、$y'(0)$ 解 $C_1$、$C_2$。只對 $y_h$ 代初始條件是常見錯誤：$y_p$ 在 $0$ 也有值。"]}],"workedExamples":[{"title":"指數右邊","prompt":"$y''-y=e^{2x}$，$y(0)=\\frac{1}{3}$，$y'(0)=\\frac{2}{3}$","problemId":"ode-p2-002","steps":["齊次：$r^2-1=0$，$r=\\pm1$，$y_h=C_1e^x+C_2e^{-x}$。$e^{2x}$ 不在其中，可以直接猜。","猜 $y_p=Ae^{2x}$：$y_p''=4Ae^{2x}$，代入 $4A-A=1$，$A=\\frac{1}{3}$。","$y=C_1e^x+C_2e^{-x}+\\frac{e^{2x}}{3}$。$y(0)$：$C_1+C_2+\\frac{1}{3}=\\frac{1}{3}$。$y'(0)$：$C_1-C_2+\\frac{2}{3}=\\frac{2}{3}$。","$C_1+C_2=0$ 且 $C_1-C_2=0$，所以 $C_1=C_2=0$。"],"answer":"$y=\\frac{e^{2x}}{3}$"},{"title":"多項式右邊：一次多項式要猜完整","prompt":"$y''-3y'+2y=2x$，$y(0)=\\frac{3}{2}$，$y'(0)=1$","problemId":"ode-p2-004","steps":["齊次：$r=1$、$2$，$y_h=C_1e^x+C_2e^{2x}$。","右邊是一次多項式，猜 $y_p=Ax+B$（不能只猜 $Ax$）。$y_p'=A$，$y_p''=0$。","代入：$-3A+2(Ax+B)=2x$。比較 $x$ 的係數 $2A=2$，$A=1$；常數項 $-3A+2B=0$，$B=\\frac{3}{2}$。","$y=C_1e^x+C_2e^{2x}+x+\\frac{3}{2}$。$y(0)$：$C_1+C_2=0$。$y'(0)$：$C_1+2C_2+1=1$。所以 $C_1=C_2=0$。"],"answer":"$y=x+\\frac{3}{2}$"},{"title":"修正規則","prompt":"$y''+y'=1$，$y(0)=0$，$y'(0)=0$","problemId":"ode-p2-005","steps":["齊次：$r^2+r=r(r+1)=0$，$r=0$、$-1$，$y_h=C_1+C_2e^{-x}$。","右邊是常數，本來猜 $A$，但常數是齊次解（$r=0$），代入只會得 $0=1$。$r=0$ 是單根，乘一個 $x$：猜 $y_p=Ax$。","$y_p'=A$、$y_p''=0$，代入得 $A=1$，$y_p=x$。","$y=C_1+C_2e^{-x}+x$。$y(0)$：$C_1+C_2=0$。$y'(0)$：$-C_2+1=0$，$C_2=1$，$C_1=-1$。"],"answer":"$y=x-1+e^{-x}$"}],"pitfalls":["右邊是 $\\cos\\omega x$ 只猜 $A\\cos\\omega x$，漏了 $B\\sin\\omega x$。","右邊是 $2x$ 只猜 $Ax$，漏了常數項 $B$。","猜到齊次解沒有發現，代入得 $0={}$ 常數，才知道要乘 $x$。","初始條件只代進 $y_h$，忘了 $y_p$。","重根時只乘一個 $x$：仍然和 $xe^{rx}$ 重複，要乘 $x^2$。"],"checks":[{"ask":"$y''+2y'+y=3\\cos x$，特解要猜？","options":[{"label":"$A\\cos x+B\\sin x$","correct":true},{"label":"$A\\cos x$","why":"$y'$ 會出現 $\\sin x$，只猜 $\\cos$ 的話 $\\sin$ 的係數對不起來。"},{"label":"$x(A\\cos x+B\\sin x)$","why":"乘 $x$ 只在 $\\cos x$ 是齊次解時才需要；這裡特徵根是 $-1$（重根），$\\cos x$ 不是齊次解。"}]},{"ask":"$y''-4y=e^{2x}$，特解要猜？","options":[{"label":"$Axe^{2x}$","correct":true},{"label":"$Ae^{2x}$","why":"$r=\\pm2$，$e^{2x}$ 是齊次解，代入左邊得 $4A-4A=0$，永遠等不到 $e^{2x}$。"},{"label":"$Ax^2e^{2x}$","why":"$x^2$ 只在 $2$ 是重根時需要；這裡 $2$ 是單根，乘一個 $x$ 就夠。"}]},{"ask":"$y''+y=2$ 的一個特解是？","options":[{"label":"$y_p=2$","correct":true},{"label":"$y_p=2x$","why":"代入得 $0+2x=2x\\ne 2$。右邊是常數，就猜常數 $A$，$A=2$。"},{"label":"$y_p=1$","why":"代入得 $0+1=1\\ne 2$：常數的 $y''$ 是 $0$，所以 $A$ 本身就要等於 $2$。"}]},{"ask":"初始條件要代進哪裡？","options":[{"label":"完整的 $y_h+y_p$","correct":true},{"label":"只代進 $y_h$","why":"$y_p$ 在 $x=0$ 也有值，例如 $y_p=x+\\frac{3}{2}$ 在 $0$ 是 $\\frac{3}{2}$，漏掉它常數會算錯。"},{"label":"只代進 $y_p$","why":"$y_p$ 沒有任意常數，沒東西可以解；常數在 $y_h$ 裡。"}]}],"practice":[{"id":"ode-p2-002","core":true},{"id":"ode-p2-004","core":true},{"id":"ode-p2-003","core":true},{"id":"ode-p2-001","core":true},{"id":"ode-p2-005","core":true},{"id":"ode-p2-006","challenge":true,"note":"挑戰：$\\cos x$ 是齊次解，要猜 $x(A\\cos x+B\\sin x)$。"}]},"variation-of-parameters":{"id":"variation-of-parameters","prerequisites":["undetermined-coefficients","second-order-linear"],"next":["harmonic-oscillator"],"related":[],"objectives":["知道待定係數只對多項式、指數、$\\sin/\\cos$ 有效，右邊是 $\\sec x$、$\\ln x$、$\\frac{1}{x}$ 時要用參數變異。","把方程先化成 $y''+p(x)y'+q(x)y=g(x)$，用 Wronskian 公式寫出 $u_1'$、$u_2'$。","積分出 $u_1$、$u_2$，組合成特解 $y_p=u_1y_1+u_2y_2$。"],"concept":[{"heading":"① 猜不到的時候","body":["$y''+y=\\sec x$：$\\sec x$ 微分會生出 $\\sec x\\tan x$、$\\sec x\\tan^2x$……永遠不會回到有限幾項的家族，待定係數猜不出來。","參數變異的想法：齊次解是 $C_1y_1+C_2y_2$（這裡 $y_1=\\cos x$、$y_2=\\sin x$）。把常數 $C_1$、$C_2$ 換成函數 $u_1(x)$、$u_2(x)$，試 $y_p=u_1y_1+u_2y_2$。","名字就是這個意思：齊次解裡的參數（常數）被允許隨 $x$ 變化。常數的時候左邊只能得到 $0$；讓它們會動，左邊才有機會等於 $g$。剩下的問題是：$u_1$、$u_2$ 要怎麼選。"]},{"heading":"② 公式","body":["方程必須先寫成首項係數 $1$ 的標準形 $y''+p(x)y'+q(x)y=g(x)$（$2y''+\\dots$ 要先全部除以 $2$）。$y_1$、$y_2$ 是兩個獨立的齊次解，Wronskian $W=y_1y_2'-y_1'y_2$。則："],"tex":["u_1' = -\\frac{y_2\\,g}{W},\\qquad u_2' = \\frac{y_1\\,g}{W},\\qquad y_p = u_1y_1 + u_2y_2"]},{"heading":"③ 公式從哪裡來","body":["兩個未知函數只有一個方程，可以再加一個條件。$y_p'=u_1y_1'+u_2y_2'+(u_1'y_1+u_2'y_2)$，我們規定括號 $u_1'y_1+u_2'y_2=0$，這樣 $y_p'$ 裡沒有 $u'$，再微分一次也不會出現 $u''$。","$y_p''=u_1y_1''+u_2y_2''+u_1'y_1'+u_2'y_2'$。代入方程，因為 $y_1$、$y_2$ 是齊次解，含 $u_1$、$u_2$ 本身的項全部消掉，只剩 $u_1'y_1'+u_2'y_2'=g$。","兩條一次方程 $u_1'y_1+u_2'y_2=0$、$u_1'y_1'+u_2'y_2'=g$，用 Cramer 法則解出上面的公式；分母就是 $W$，兩個解獨立時 $W\\ne 0$。"],"collapsible":true},{"heading":"④ 適用範圍與小技巧","body":["只要 $p$、$q$、$g$ 在某個區間上連續，而且已知兩個獨立的齊次解，這個方法在那個區間上都有效，不限常係數。代價是要做兩個積分，有時積不出初等形式。","積 $u_1$、$u_2$ 時不用加常數：加了只會多出 $C_1y_1+C_2y_2$，那本來就在 $y_h$ 裡。同理，$y_p$ 裡和齊次解重複的項可以丟掉。"]}],"workedExamples":[{"title":"$\\sec x$","prompt":"求 $y''+y=\\sec x$ 在 $-\\frac{\\pi}{2}<x<\\frac{\\pi}{2}$ 的一個特解。","steps":["已是標準形，$g=\\sec x$（在這個區間連續）。$y_1=\\cos x$、$y_2=\\sin x$，$W=\\cos x\\cdot\\cos x-(-\\sin x)\\cdot\\sin x=1$。","$u_1'=-\\frac{\\sin x\\cdot\\sec x}{1}=-\\tan x$，$u_1=\\ln(\\cos x)$（區間上 $\\cos x>0$，不用絕對值）。","$u_2'=\\frac{\\cos x\\cdot\\sec x}{1}=1$，$u_2=x$。","$y_p=\\cos x\\cdot\\ln(\\cos x)+x\\sin x$。"],"answer":"$y_p=\\cos x\\ln(\\cos x)+x\\sin x$；通解再加 $C_1\\cos x+C_2\\sin x$"},{"title":"重根的齊次解","prompt":"求 $y''-2y'+y=\\frac{e^x}{x}$（$x>0$）的一個特解。","steps":["齊次：$(r-1)^2=0$，$y_1=e^x$、$y_2=xe^x$。$W=e^x\\cdot(1+x)e^x-e^x\\cdot xe^x=e^{2x}$。","$u_1'=-\\frac{xe^x\\cdot(e^x/x)}{e^{2x}}=-1$，$u_1=-x$。","$u_2'=\\frac{e^x\\cdot(e^x/x)}{e^{2x}}=\\frac{1}{x}$，$u_2=\\ln x$（$x>0$）。","$y_p=-x\\cdot e^x+\\ln x\\cdot xe^x$。$-xe^x$ 是齊次解，可以丟掉。"],"answer":"$y_p=xe^x\\ln x$"},{"title":"寫成一個積分","prompt":"用參數變異寫出 $y''+y=g(x)$、$y(0)=y'(0)=0$ 的解，並代 $g=\\cos x$。","steps":["$y_1=\\cos x$、$y_2=\\sin x$、$W=1$。從 $0$ 積到 $x$：$u_1=-\\int_0^x\\sin t\\cdot g(t)\\,dt$，$u_2=\\int_0^x\\cos t\\cdot g(t)\\,dt$。","$y=u_1\\cos x+u_2\\sin x=\\int_0^x(\\sin x\\cos t-\\cos x\\sin t)\\,g(t)\\,dt=\\int_0^x\\sin(x-t)\\,g(t)\\,dt$。","從 $0$ 開始積，$u_1(0)=u_2(0)=0$，可以驗證 $y(0)=y'(0)=0$。","$g=\\cos x$：$\\int_0^x\\sin(x-t)\\cos t\\,dt=\\frac{x\\sin x}{2}$。"],"answer":"$y=\\int_0^x\\sin(x-t)\\,g(t)\\,dt$；$g=\\cos x$ 時 $y=\\frac{x\\sin x}{2}$"}],"pitfalls":["沒有先除以首項係數：$2y''+2y=\\sec x$ 的 $g$ 是 $\\frac{\\sec x}{2}$。","$W$ 的順序弄反，整個特解差一個負號。","$u_1'$ 公式前面的負號漏掉。","在 $g$ 不連續的地方用：$\\sec x$ 的公式只在 $\\cos x\\ne 0$ 的區間內成立。"],"checks":[{"ask":"$2y''+2y=\\sec x$ 套參數變異公式時，$g(x)$ 是？","options":[{"label":"$\\frac{\\sec x}{2}$","correct":true},{"label":"$\\sec x$","why":"公式是在 $y''$ 係數為 $1$ 的標準形下推導的，要先全部除以 $2$。"},{"label":"$2\\sec x$","why":"方向反了：化成標準形是除以 $2$，不是乘 $2$。"}]},{"ask":"$W(\\cos x,\\sin x)=y_1y_2'-y_1'y_2$ 是？","options":[{"label":"$1$","correct":true},{"label":"$-1$","why":"$\\cos x\\cdot\\cos x-(-\\sin x)\\cdot\\sin x=1$。$-1$ 是 $W(\\sin x,\\cos x)$，順序換了。"},{"label":"$0$","why":"$W=0$ 代表兩個解是彼此的常數倍；$\\cos x$ 與 $\\sin x$ 不是。"}]},{"ask":"哪一個方程用待定係數做不出來，要用參數變異？","options":[{"label":"$y''+y=\\tan x$","correct":true},{"label":"$y''+y=e^{2x}$","why":"指數微分還是指數，猜 $Ae^{2x}$ 就行。"},{"label":"$y''+y=x^2$","why":"多項式猜 $Ax^2+Bx+C$ 就行。"}]},{"ask":"為什麼可以規定 $u_1'y_1+u_2'y_2=0$？","options":[{"label":"兩個未知函數只被一個方程限制，可以自己再加一個方便的條件","correct":true},{"label":"因為 $y_1$、$y_2$ 是齊次解，這個式子自動成立","why":"它不是自動成立的，是我們選的條件；選它是為了讓 $u''$ 不出現。"},{"label":"為了讓 $u_1$、$u_2$ 是常數","why":"$u_1$、$u_2$ 是常數的話 $y_p$ 就只是齊次解，不可能等於 $g$。"}]}],"practice":[{"id":"der-060","core":true},{"id":"der-059","core":true},{"id":"der-061","core":true},{"id":"der-064"},{"id":"int-060","challenge":true,"note":"挑戰：這個積分正是 $y''+y=\\cos x$、零初始條件的解（範例 3）。"}]},"harmonic-oscillator":{"id":"harmonic-oscillator","prerequisites":["complex-roots"],"next":["damped-oscillator"],"related":["spring-work"],"objectives":["從牛頓第二定律與虎克定律寫出 $mx''+kx=0$，說出 $\\omega_0=\\sqrt{k/m}$ 的物理意義。","用初始位置與初速度解出 $x(t)$，並改寫成 $A\\cos(\\omega_0t-\\varphi)$，讀出振幅與週期。","用能量守恆 $\\frac{1}{2}mx'^2+\\frac{1}{2}kx^2={}$ 常數 檢查答案。"],"concept":[{"heading":"① 從物理寫出方程","body":["質量 $m$ 的木塊接在彈簧上，$x$ 是離開平衡位置的位移。虎克定律：彈簧的力是 $-kx$（拉長就往回拉，壓縮就往外推），$k>0$ 是彈簧常數。牛頓第二定律 力 $={}$ 質量 $\\times$ 加速度："],"tex":["m x'' = -kx \\quad\\Longleftrightarrow\\quad x'' + \\omega_0^2 x = 0,\\qquad \\omega_0=\\sqrt{k/m}"]},{"heading":"② 解：純虛根給 $\\sin$、$\\cos$","body":["特徵方程 $r^2+\\omega_0^2=0$，$r=\\pm i\\omega_0$（〈複數根〉，$\\alpha=0$）。通解 $x(t)=C_1\\cos\\omega_0t+C_2\\sin\\omega_0t$。","代 $t=0$：$C_1=x(0)$；$x'(0)=\\omega_0C_2$，所以 $C_2=\\frac{x'(0)}{\\omega_0}$。","$\\omega_0$ 是角頻率（每秒轉幾弧度），週期 $T=\\frac{2\\pi}{\\omega_0}=2\\pi\\sqrt{m/k}$：彈簧越硬振越快，木塊越重振越慢。週期跟振幅無關：拉遠一點，回復力也比較大，剛好抵銷。"]},{"heading":"③ 振幅與相位","body":["$C_1\\cos\\omega_0t+C_2\\sin\\omega_0t$ 可以合成一個餘弦 $A\\cos(\\omega_0t-\\varphi)$，其中 $A=\\sqrt{C_1^2+C_2^2}$，$\\cos\\varphi=\\frac{C_1}{A}$、$\\sin\\varphi=\\frac{C_2}{A}$。$A$ 是振幅（離平衡最遠多少），$\\varphi$ 說明最遠點發生在什麼時候。","$\\varphi$ 要看 $C_1$、$C_2$ 的正負決定象限，不能只用 $\\tan\\varphi=\\frac{C_2}{C_1}$。"]},{"heading":"④ 能量守恆","body":["動能 $\\frac{1}{2}mx'^2$ 加彈性位能 $\\frac{1}{2}kx^2$ 不隨時間改變：微分得 $x'(mx''+kx)=0$。木塊在平衡點最快、在最遠點瞬間靜止，能量在兩種形式之間來回交換。這是檢查答案的好方法。"]}],"workedExamples":[{"title":"從物理量到 $x(t)$","prompt":"$m=2$ kg、$k=18$ N/m 的彈簧系統，木塊從平衡位置以 $3$ m/s 出發。求 $x(t)$、振幅、週期。","steps":["$\\omega_0=\\sqrt{k/m}=\\sqrt9=3$（rad/s）。方程 $x''+9x=0$。","$x(0)=0$ 給 $C_1=0$；$x'(0)=3$ 給 $C_2=\\frac{3}{\\omega_0}=1$。","$x(t)=\\sin 3t$（公尺）。振幅 $1$ m，週期 $\\frac{2\\pi}{3}\\approx2.09$ 秒。"],"answer":"$x(t)=\\sin 3t$，振幅 $1$ m，週期 $\\frac{2\\pi}{3}$ 秒"},{"title":"合成振幅與相位","prompt":"$x''+4x=0$，$x(0)=3$，$x'(0)=8$。寫成 $A\\cos(2t-\\varphi)$。","steps":["$\\omega_0=2$。$C_1=x(0)=3$，$C_2=\\frac{x'(0)}{\\omega_0}=\\frac{8}{2}=4$。","$x=3\\cos 2t+4\\sin 2t$。$A=\\sqrt{3^2+4^2}=5$。","$\\cos\\varphi=\\frac{3}{5}>0$、$\\sin\\varphi=\\frac{4}{5}>0$，$\\varphi$ 在第一象限：$\\varphi=\\arctan\\frac{4}{3}\\approx0.927$。","最大速度 $A\\omega_0=10$。"],"answer":"$x=5\\cos\\left(2t-\\arctan\\frac{4}{3}\\right)$"},{"title":"用能量檢查","prompt":"承上題，取 $m=1$、$k=4$，驗證總能量不變。","steps":["$t=0$：動能 $\\frac{1}{2}\\cdot1\\cdot8^2=32$，位能 $\\frac{1}{2}\\cdot4\\cdot3^2=18$，總和 $50$。","在最遠點 $x=\\pm5$，速度為 $0$：位能 $\\frac{1}{2}\\cdot4\\cdot5^2=50$，動能 $0$。","任何時刻 $\\frac{1}{2}x'^2+2x^2$ 都是 $50$。"],"answer":"總能量 $50$（焦耳）"}],"pitfalls":["$C_2$ 寫成 $x'(0)$，忘了除以 $\\omega_0$。","把角頻率 $\\omega_0$ 當成每秒振動次數；次數是 $\\frac{\\omega_0}{2\\pi}$。","振幅寫成 $|C_1|+|C_2|$，正確是 $\\sqrt{C_1^2+C_2^2}$。","只用 $\\tan\\varphi=\\frac{C_2}{C_1}$ 定相位，象限錯了差 $\\pi$。","以為振幅越大週期越長：簡諧振盪的週期與振幅無關。"],"checks":[{"ask":"同一根彈簧，木塊質量變成 4 倍，週期變成？","options":[{"label":"$2$ 倍","correct":true},{"label":"$4$ 倍","why":"$T=2\\pi\\sqrt{m/k}$，$m$ 在根號裡：$\\sqrt4=2$。"},{"label":"$\\frac{1}{2}$","why":"方向反了：越重越慢，週期變長。"}]},{"ask":"$x=6\\cos t+8\\sin t$ 的振幅是？","options":[{"label":"$10$","correct":true},{"label":"$14$","why":"$\\cos$ 與 $\\sin$ 不會同時達到最大，係數不能直接相加；$A=\\sqrt{36+64}=10$。"},{"label":"$8$","why":"只看較大的係數漏了 $\\cos$ 那一項的貢獻；$A=\\sqrt{6^2+8^2}$。"}]},{"ask":"把木塊拉得更遠再放手（振幅變 $2$ 倍），週期？","options":[{"label":"不變","correct":true},{"label":"變 $2$ 倍","why":"路程變 $2$ 倍，但回復力與速度也都變 $2$ 倍，剛好抵銷；$T=\\frac{2\\pi}{\\omega_0}$ 裡沒有振幅。"},{"label":"變一半","why":"週期只由 $k$ 與 $m$ 決定，跟拉多遠無關。"}]},{"ask":"木塊經過平衡位置 $x=0$ 時：","options":[{"label":"速度最大，動能最大","correct":true},{"label":"速度為 $0$","why":"速度為 $0$ 的是最遠點（轉折點）；平衡點位能為 $0$，能量全是動能。"},{"label":"加速度最大","why":"加速度是 $-\\omega_0^2x$，在 $x=0$ 時是 $0$；最大加速度在最遠點。"}]}],"practice":[{"id":"ode-h2-002","core":true},{"id":"gap-der-ode-004","core":true},{"id":"ode-h2-007","core":true}]},"damped-oscillator":{"id":"damped-oscillator","prerequisites":["harmonic-oscillator","repeated-roots","complex-roots"],"next":["driven-oscillator"],"related":["distinct-real-roots"],"objectives":["加上與速度成正比的阻力，寫出 $x''+2\\gamma x'+\\omega_0^2x=0$，並說出 $\\gamma$ 的物理意義。","比較 $\\gamma$ 與 $\\omega_0$，分辨欠阻尼、臨界阻尼、過阻尼，寫出各自的解。","讀出欠阻尼的振盪角頻率 $\\omega_d=\\sqrt{\\omega_0^2-\\gamma^2}$ 與包絡線 $e^{-\\gamma t}$。"],"concept":[{"heading":"① 加上阻力","body":["木塊在空氣或液體裡運動，會受到跟速度方向相反、大小約與速度成正比的阻力 $-cx'$（$c>0$）。牛頓第二定律變成 $mx''=-kx-cx'$。除以 $m$，令 $2\\gamma=\\frac{c}{m}$、$\\omega_0^2=\\frac{k}{m}$："],"tex":["x'' + 2\\gamma x' + \\omega_0^2 x = 0"]},{"heading":"② 特徵根決定三種行為","body":["$r^2+2\\gamma r+\\omega_0^2=0$，$r=-\\gamma\\pm\\sqrt{\\gamma^2-\\omega_0^2}$。關鍵是比較 $\\gamma$ 與 $\\omega_0$：","欠阻尼 $\\gamma<\\omega_0$：根是 $-\\gamma\\pm i\\omega_d$，$\\omega_d=\\sqrt{\\omega_0^2-\\gamma^2}$。$x=e^{-\\gamma t}(C_1\\cos\\omega_dt+C_2\\sin\\omega_dt)$，一邊振一邊衰減，包絡線是 $e^{-\\gamma t}$，而且振得比沒有阻尼時慢（$\\omega_d<\\omega_0$）。","臨界阻尼 $\\gamma=\\omega_0$：重根 $-\\gamma$，$x=(C_1+C_2t)e^{-\\gamma t}$，不振盪。","過阻尼 $\\gamma>\\omega_0$：兩個負實根，$x=C_1e^{r_1t}+C_2e^{r_2t}$，不振盪，慢慢回到平衡，最多穿過平衡點一次。"]},{"heading":"③ 物理意義","body":["三種情況的解都 $\\to0$：阻力一直在消耗能量。能量 $E=\\frac{1}{2}mx'^2+\\frac{1}{2}kx^2$ 的變化率 $\\frac{dE}{dt}=x'(mx''+kx)=-cx'^2\\le 0$。","汽車避震器設計在接近臨界阻尼：阻尼太小車子壓過坑會彈個不停，太大則回彈太慢。在所有 $\\gamma$ 中，臨界阻尼的指數衰減率最大。"]}],"workedExamples":[{"title":"欠阻尼","prompt":"$x''+2x'+5x=0$，$x(0)=1$，$x'(0)=-1$。判斷類型並求 $x(t)$。","problemId":"ode-h2-005","steps":["$2\\gamma=2\\to\\gamma=1$；$\\omega_0^2=5\\to\\omega_0=\\sqrt5\\approx2.24$。$\\gamma<\\omega_0$，欠阻尼。","$\\omega_d=\\sqrt{5-1}=2$。$x=e^{-t}(C_1\\cos 2t+C_2\\sin 2t)$。","$x(0)=1$：$C_1=1$。$x'(0)=-C_1+2C_2=-1$：$C_2=0$。","物理上：振幅照 $e^{-t}$ 縮小，大約每 $\\pi$ 秒（$\\frac{2\\pi}{\\omega_d}$）完成一次完整振動。"],"answer":"$x(t)=e^{-t}\\cos 2t$"},{"title":"臨界阻尼","prompt":"$x''+4x'+4x=0$，$x(0)=1$，$x'(0)=0$（拉開 $1$ 再靜止放手）","steps":["$\\gamma=2$、$\\omega_0=2$，$\\gamma=\\omega_0$，臨界阻尼。重根 $r=-2$，$x=(C_1+C_2t)e^{-2t}$。","$x(0)=1$：$C_1=1$。$x'=C_2e^{-2t}-2(C_1+C_2t)e^{-2t}$，$x'(0)=C_2-2=0$，$C_2=2$。","$t>0$ 時 $(1+2t)e^{-2t}>0$：木塊回到平衡但不越過。"],"answer":"$x(t)=(1+2t)e^{-2t}$"},{"title":"過阻尼","prompt":"$x''+5x'+4x=0$，$x(0)=1$，$x'(0)=0$","steps":["$\\gamma=2.5$、$\\omega_0=2$，$\\gamma>\\omega_0$，過阻尼。$r^2+5r+4=(r+1)(r+4)$，$r=-1$、$-4$。","$x=C_1e^{-t}+C_2e^{-4t}$。$x(0)$：$C_1+C_2=1$。$x'(0)$：$-C_1-4C_2=0$。","$C_1=\\frac{4}{3}$、$C_2=-\\frac{1}{3}$。$e^{-4t}$ 很快消失，之後由 $e^{-t}$ 主導，比上一題的 $e^{-2t}$ 回得慢。"],"answer":"$x(t)=\\frac{4e^{-t}-e^{-4t}}{3}$"}],"pitfalls":["拿 $x'$ 的係數 $2\\gamma$ 直接和 $\\omega_0$ 比，忘了先除以 $2$。","拿 $x$ 的係數 $\\omega_0^2$ 和 $\\gamma$ 比，忘了開根號。","以為欠阻尼仍以 $\\omega_0$ 振動：實際角頻率是 $\\omega_d=\\sqrt{\\omega_0^2-\\gamma^2}$。","以為阻尼越大回得越快：超過臨界之後，阻尼越大反而回得越慢。"],"checks":[{"ask":"$x''+6x'+25x=0$ 屬於哪一種？","options":[{"label":"欠阻尼，$\\omega_d=4$","correct":true},{"label":"過阻尼","why":"你拿 $2\\gamma=6$ 和 $\\omega_0=5$ 比。應該是 $\\gamma=3$ 和 $\\omega_0=5$ 比，$3<5$。"},{"label":"欠阻尼，$\\omega_d=5$","why":"$5$ 是 $\\omega_0$；阻尼讓振動變慢，$\\omega_d=\\sqrt{25-9}=4$。"}]},{"ask":"$m=1$、$k=9$，阻尼係數 $c$ 是多少時剛好臨界阻尼？","options":[{"label":"$c=6$","correct":true},{"label":"$c=3$","why":"$3$ 是臨界時的 $\\gamma$（$=\\omega_0=3$），但 $c=2m\\gamma=6$。"},{"label":"$c=9$","why":"$9$ 是 $k$；臨界條件是 $c^2=4mk=36$。"}]},{"ask":"有阻尼時，總能量 $\\frac{1}{2}mx'^2+\\frac{1}{2}kx^2$ 會？","options":[{"label":"隨時間遞減（只在 $x'=0$ 的瞬間不減）","correct":true},{"label":"保持不變","why":"那是沒有阻尼的情況；有阻尼時 $\\frac{dE}{dt}=-cx'^2\\le 0$。"},{"label":"在有限時間內降到剛好 $0$ 後停住","why":"解是指數衰減，越來越接近 $0$，但在有限時間內不會剛好停住。"}]},{"ask":"$x=e^{-t}\\cos 2t$ 的振幅降到一開始的一半，大約要多久？","options":[{"label":"$t=\\ln 2\\approx0.69$","correct":true},{"label":"$t=\\frac{1}{2}$","why":"振幅是包絡線 $e^{-t}$，要解 $e^{-t}=\\frac{1}{2}$，得 $t=\\ln 2$，不是線性的 $\\frac{1}{2}$。"},{"label":"$t=\\frac{\\ln 2}{2}$","why":"那是 $e^{-2t}$ 的半衰期；這裡的指數是 $-t$，$\\cos 2t$ 裡的 $2$ 只管振盪快慢。"}]}],"practice":[{"id":"ode-h2-005","core":true},{"id":"ode-h2-004","core":true}]},"driven-oscillator":{"id":"driven-oscillator","prerequisites":["damped-oscillator","undetermined-coefficients"],"next":["resonance"],"related":["complex-roots"],"objectives":["寫出受週期外力推動的方程 $x''+2\\gamma x'+\\omega_0^2x=F_0\\cos\\omega t$，說出解 $={}$ 暫態 $+$ 穩態。","用待定係數求穩態解，並用公式 $A(\\omega)=\\frac{F_0}{\\sqrt{(\\omega_0^2-\\omega^2)^2+(2\\gamma\\omega)^2}}$ 讀出振幅。","說得出有阻尼時，長時間後系統以外力的頻率 $\\omega$ 振動，與初始條件無關。"],"concept":[{"heading":"① 有人在推","body":["在阻尼振盪上加一個週期外力 $mF_0\\cos\\omega t$（例如馬達、地震、聲波）。除以 $m$："],"tex":["x'' + 2\\gamma x' + \\omega_0^2 x = F_0\\cos\\omega t"]},{"heading":"② 解 $={}$ 暫態 $+$ 穩態","body":["這是非齊次方程，通解是齊次解加一個特解（〈待定係數〉）。","齊次解就是〈阻尼振盪〉的解，帶著 $e^{-\\gamma t}$，$\\gamma>0$ 時會消失，叫做暫態。初始條件只影響它。","特解用待定係數猜 $a\\cos\\omega t+b\\sin\\omega t$（$\\cos$ 與 $\\sin$ 都要），它不會消失，叫做穩態。長時間之後，系統以外力的角頻率 $\\omega$ 振動，不是以自己的 $\\omega_0$ 或 $\\omega_d$。","生活裡的例子：洗衣機脫水時機身先亂抖一陣，轉速穩定之後，機身就跟著滾筒的轉速規律地振動。"]},{"heading":"③ 穩態振幅","body":["把 $a$、$b$ 解出來，穩態可以寫成 $A\\cos(\\omega t-\\delta)$，振幅只跟 $\\omega$ 有關：","$\\delta$ 是位移落後外力的相位角（$0<\\delta<\\pi$）。推得慢（$\\omega<\\omega_0$）時 $\\delta$ 接近 $0$，木塊幾乎和力同步；$\\omega=\\omega_0$ 時 $\\delta=\\frac{\\pi}{2}$；推得快（$\\omega>\\omega_0$）時 $\\delta$ 接近 $\\pi$，木塊和力幾乎反向。$\\tan\\delta$ 只定出 $\\delta$ 的正切，$\\omega>\\omega_0$ 時分母為負，$\\delta$ 在 $\\frac{\\pi}{2}$ 與 $\\pi$ 之間。"],"tex":["A(\\omega)=\\frac{F_0}{\\sqrt{(\\omega_0^2-\\omega^2)^2+(2\\gamma\\omega)^2}},\\qquad \\tan\\delta=\\frac{2\\gamma\\omega}{\\omega_0^2-\\omega^2}"]},{"heading":"④ 推導（用複數比較快）","body":["$F_0\\cos\\omega t$ 是 $F_0e^{i\\omega t}$ 的實部。試 $x=Ze^{i\\omega t}$：$x'=i\\omega Ze^{i\\omega t}$、$x''=-\\omega^2Ze^{i\\omega t}$，代入得 $Z(\\omega_0^2-\\omega^2+2i\\gamma\\omega)=F_0$。","所以 $Z=\\frac{F_0}{\\omega_0^2-\\omega^2+2i\\gamma\\omega}$，穩態解是 $Ze^{i\\omega t}$ 的實部（係數都是實數，實部仍是解，見〈複數根〉）。振幅 $|Z|$ 就是上面的公式；$\\delta$ 是分母的輻角，代表位移落後外力多少。"],"collapsible":true},{"heading":"⑤ 讀公式","body":["$\\omega$ 很小（推得很慢）：$A\\approx\\frac{F_0}{\\omega_0^2}$，木塊幾乎跟著力靜態地移動。$\\omega$ 很大：$A\\approx\\frac{F_0}{\\omega^2}$，推太快木塊來不及反應。中間 $\\omega$ 接近 $\\omega_0$ 時分母最小、振幅最大，這是下一課〈共振〉。"]}],"workedExamples":[{"title":"沒有阻尼，從靜止開始推","prompt":"$x''+4x=3\\cos t$，$x(0)=0$，$x'(0)=0$","steps":["$\\omega_0=2$、$\\omega=1$，不相等。$\\cos t$ 不是齊次解，猜 $x_p=A\\cos t$（方程裡沒有 $x'$，$\\sin t$ 的係數會是 $0$）。","代入：$-A+4A=3$，$A=1$。$x=C_1\\cos 2t+C_2\\sin 2t+\\cos t$。","$x(0)=0$：$C_1+1=0$，$C_1=-1$。$x'(0)=2C_2=0$，$C_2=0$。","$x=\\cos t-\\cos 2t$：沒有阻尼，自然頻率那一項不會消失，兩個頻率一直疊在一起。"],"answer":"$x(t)=\\cos t-\\cos 2t$"},{"title":"有阻尼的穩態","prompt":"$x''+2x'+2x=10\\cos 2t$，求穩態解與振幅。","steps":["$\\gamma=1$、$\\omega_0^2=2$、$\\omega=2$。猜 $x_p=a\\cos 2t+b\\sin 2t$。","$x_p'=-2a\\sin 2t+2b\\cos 2t$，$x_p''=-4a\\cos 2t-4b\\sin 2t$。","代入比較係數：$\\cos$：$-4a+4b+2a=10$，即 $-2a+4b=10$；$\\sin$：$-4b-4a+2b=0$，即 $b=-2a$。","$-2a-8a=10$，$a=-1$、$b=2$。振幅 $\\sqrt{1+4}=\\sqrt5$，與公式 $\\frac{10}{\\sqrt{(2-4)^2+(2\\cdot1\\cdot2)^2}}=\\frac{10}{\\sqrt{20}}=\\sqrt5$ 一致。"],"answer":"$x_p=-\\cos 2t+2\\sin 2t$，振幅 $\\sqrt5$"},{"title":"完整解：暫態會消失","prompt":"同上方程，$x(0)=0$，$x'(0)=0$，求 $x(t)$。","steps":["齊次：$r^2+2r+2=0$，$r=-1\\pm i$。$x=e^{-t}(C_1\\cos t+C_2\\sin t)-\\cos 2t+2\\sin 2t$。","$x(0)=0$：$C_1-1=0$，$C_1=1$。","$x'(0)=-C_1+C_2+4=0$，$C_2=-3$。","$e^{-t}$ 那一項幾秒後就小到看不見，剩下穩態 $-\\cos 2t+2\\sin 2t$。換一組初始條件只會改 $C_1$、$C_2$，穩態不變。"],"answer":"$x(t)=e^{-t}(\\cos t-3\\sin t)-\\cos 2t+2\\sin 2t$"}],"pitfalls":["有 $x'$ 項時只猜 $a\\cos\\omega t$，漏了 $b\\sin\\omega t$。","初始條件代進穩態解，忘了暫態那一項。","以為長時間後以自然頻率 $\\omega_0$ 振動：有阻尼時留下來的是外力的頻率 $\\omega$。","振幅公式漏了 $2\\gamma\\omega$ 那一項，或把 $\\omega_0^2-\\omega^2$ 寫成 $\\omega_0-\\omega$。"],"checks":[{"ask":"有阻尼（$\\gamma>0$）的受迫振盪，很久以後木塊以什麼角頻率振動？","options":[{"label":"外力的 $\\omega$","correct":true},{"label":"欠阻尼的 $\\omega_d$","why":"$\\omega_d$ 屬於齊次解（暫態），它帶著 $e^{-\\gamma t}$，會消失。"},{"label":"不振動，停在平衡點","why":"外力一直在推，持續提供能量，穩態解不會消失。"}]},{"ask":"$x''+9x=8\\cos t$ 的穩態解振幅是？","options":[{"label":"$1$","correct":true},{"label":"$\\frac{8}{9}$","why":"忘了 $x''$ 的貢獻：猜 $A\\cos t$ 代入得 $(9-1)A=8$，$A=1$。"},{"label":"$\\frac{8}{10}$","why":"符號錯了：$x''=-A\\cos t$，是 $9-1$，不是 $9+1$。"}]},{"ask":"換一組初始條件，穩態解會改變嗎？","options":[{"label":"不會，初始條件只影響暫態的常數","correct":true},{"label":"會，振幅跟著 $x(0)$ 改變","why":"穩態解是特解，它的係數由方程本身決定，跟 $x(0)$、$x'(0)$ 無關。"},{"label":"只有 $x'(0)$ 會影響它","why":"兩個初始條件都只用來決定齊次解的 $C_1$、$C_2$。"}]},{"ask":"振幅公式在 $\\gamma=0$、$\\omega=\\omega_0$ 時會怎樣？","options":[{"label":"分母為 $0$，公式不能用，要另外處理","correct":true},{"label":"振幅是 $0$","why":"是分母為 $0$ 不是分子為 $0$；這時猜 $a\\cos\\omega t$ 根本失敗，因為它是齊次解（〈共振〉）。"},{"label":"振幅是 $F_0$","why":"代進去分母是 $\\sqrt0$，不是 $1$。"}]}],"practice":[{"id":"ode-p2-003","core":true,"note":"固定外力：木塊繞著新的平衡點 $x=2$ 振動。"}]},"resonance":{"id":"resonance","prerequisites":["driven-oscillator","undetermined-coefficients"],"next":[],"related":["lhopital","harmonic-oscillator"],"objectives":["沒有阻尼、外力頻率等於自然頻率時，用修正規則求出隨時間線性變大的解 $\\left(\\frac{F_0}{2\\omega_0}\\right)t\\sin\\omega_0t$。","有阻尼時，求振幅最大的外力頻率 $\\omega_r=\\sqrt{\\omega_0^2-2\\gamma^2}$ 與最大振幅。","說得出阻尼為什麼讓共振的振幅變成有限，以及這對真實結構的意義。"],"concept":[{"heading":"① 推的節奏剛好對上","body":["推鞦韆的人如果每次都在鞦韆盪回來時推一把，鞦韆會越盪越高。這是外力頻率等於系統自然頻率的情況，叫做共振。","數學上：$x''+\\omega_0^2x=F_0\\cos\\omega_0t$。上一課的猜測 $a\\cos\\omega_0t+b\\sin\\omega_0t$ 本身就是齊次解，代入左邊只得到 $0$，振幅公式分母也是 $0$。"]},{"heading":"② 修正規則：乘上 $t$","body":["照〈待定係數〉的修正規則，猜 $t(a\\cos\\omega_0t+b\\sin\\omega_0t)$。代入得 $a=0$、$b=\\frac{F_0}{2\\omega_0}$："],"tex":["x_p = \\frac{F_0}{2\\omega_0}\\, t\\sin\\omega_0 t"]},{"heading":"③ 振幅隨時間線性長大","body":["前面的 $t$ 讓振幅像 $\\frac{F_0t}{2\\omega_0}$ 一樣線性增加，沒有上限。這是沒有阻尼的理想模型：真實系統在變成無限大之前，不是阻尼開始起作用，就是彈簧不再遵守虎克定律，或結構損壞。"]},{"heading":"④ 從非共振的解取極限（直覺，不是證明）","body":["$\\omega\\ne\\omega_0$、從靜止開始時，解是 $x=\\frac{F_0(\\cos\\omega t-\\cos\\omega_0t)}{\\omega_0^2-\\omega^2}$。固定 $t$，讓 $\\omega\\to\\omega_0$：分子分母都 $\\to0$，對 $\\omega$ 用 L'Hôpital（〈L'Hôpital 法則〉），得 $\\frac{F_0t\\sin\\omega_0t}{2\\omega_0}$，正好是共振解。這說明兩個答案一致，但「解的極限還是解」需要另外證明，上面的直接代入才是證明。"],"collapsible":true},{"heading":"⑤ 有阻尼：峰值有限","body":["$\\gamma>0$ 時，〈受迫振盪〉的振幅 $A(\\omega)=\\frac{F_0}{\\sqrt{(\\omega_0^2-\\omega^2)^2+(2\\gamma\\omega)^2}}$ 分母永遠不為 $0$。令 $u=\\omega^2$，分母裡的 $(\\omega_0^2-u)^2+4\\gamma^2u$ 對 $u$ 微分 $=-2(\\omega_0^2-u)+4\\gamma^2$，為 $0$ 時 $u=\\omega_0^2-2\\gamma^2$。","所以 $\\gamma<\\frac{\\omega_0}{\\sqrt2}$ 時，振幅在 $\\omega_r=\\sqrt{\\omega_0^2-2\\gamma^2}$ 最大，最大值 $\\frac{F_0}{2\\gamma\\sqrt{\\omega_0^2-\\gamma^2}}$。$\\gamma$ 越小，峰越高、越接近 $\\omega_0$。$\\gamma\\ge\\frac{\\omega_0}{\\sqrt2}$ 時沒有峰，$A(\\omega)$ 從 $\\omega=0$ 起一路遞減。"]}],"workedExamples":[{"title":"沒有阻尼的共振","prompt":"$y''+y=\\cos x$，$y(0)=0$，$y'(0)=0$","problemId":"ode-p2-006","steps":["齊次解 $C_1\\cos x+C_2\\sin x$。右邊 $\\cos x$ 是齊次解，猜 $y_p=x(A\\cos x+B\\sin x)$。","$y_p'=A\\cos x+B\\sin x+x(-A\\sin x+B\\cos x)$，$y_p''=2(-A\\sin x+B\\cos x)+x(-A\\cos x-B\\sin x)$。","$y_p''+y_p=-2A\\sin x+2B\\cos x=\\cos x$，所以 $A=0$、$B=\\frac{1}{2}$。","$y=C_1\\cos x+C_2\\sin x+\\frac{x\\sin x}{2}$。$y(0)=0$ 給 $C_1=0$；$y'(0)=C_2=0$。"],"answer":"$y=\\frac{x\\sin x}{2}$"},{"title":"有阻尼：振幅最大的頻率","prompt":"$x''+6x'+25x=\\cos\\omega t$。$\\omega$ 多少時穩態振幅最大？最大振幅多少？","steps":["$2\\gamma=6\\to\\gamma=3$；$\\omega_0=5$。$\\gamma=3<\\frac{5}{\\sqrt2}\\approx3.54$，有峰。","$\\omega_r=\\sqrt{25-2\\cdot9}=\\sqrt7\\approx2.65$。","代回分母：$(25-7)^2+36\\cdot7=324+252=576$，$\\sqrt{576}=24$。","最大振幅 $\\frac{1}{24}$，也等於 $\\frac{F_0}{2\\gamma\\sqrt{\\omega_0^2-\\gamma^2}}=\\frac{1}{2\\cdot3\\cdot4}$。注意峰值不在 $\\omega_0=5$，也不在 $\\omega_d=4$。"],"answer":"$\\omega=\\sqrt7$，最大振幅 $\\frac{1}{24}$"},{"title":"小阻尼會放大多少","prompt":"$\\omega_0=1$、$\\gamma=0.1$、$F_0=1$。比較 $\\omega=0$（靜態推）與 $\\omega=\\omega_0$ 時的穩態振幅。","steps":["$\\omega=0$：$A=\\frac{1}{\\sqrt{1^2}}=1$。","$\\omega=1$：$A=\\frac{1}{\\sqrt{0+(2\\cdot0.1\\cdot1)^2}}=\\frac{1}{0.2}=5$。","同樣大小的力，照著節奏推，振幅放大 $5$ 倍；真正的峰在 $\\omega_r=\\sqrt{0.98}\\approx0.990$，振幅約 $5.03$，和 $\\omega_0$ 幾乎一樣。阻尼越小，放大越多。"],"answer":"靜態 $1$，$\\omega=\\omega_0$ 時 $5$（約放大 $5$ 倍）"}],"pitfalls":["共振時還猜 $a\\cos\\omega_0t+b\\sin\\omega_0t$，代入得 $0=F_0\\cos\\omega_0t$。","只猜 $t\\cdot a\\cos\\omega_0t$：$\\cos$、$\\sin$ 兩個都要乘 $t$。","以為有阻尼時峰在 $\\omega_0$ 或 $\\omega_d$：峰在 $\\sqrt{\\omega_0^2-2\\gamma^2}$。","以為阻尼大時一定有峰：$\\gamma\\ge\\frac{\\omega_0}{\\sqrt2}$ 時振幅隨 $\\omega$ 單調遞減。"],"checks":[{"ask":"$y''+4y=\\cos 2x$ 的特解要猜？","options":[{"label":"$x(A\\cos 2x+B\\sin 2x)$","correct":true},{"label":"$A\\cos 2x+B\\sin 2x$","why":"這正是齊次解，代入左邊得 $0$，等不到 $\\cos 2x$；要乘 $x$。"},{"label":"$Ax\\cos 2x$","why":"$x\\cos 2x$ 微分會生出 $x\\sin 2x$ 與 $\\sin 2x$，要配 $Bx\\sin 2x$ 才對得起來。"}]},{"ask":"沒有阻尼的共振，振幅隨時間怎麼變？","options":[{"label":"與 $t$ 成正比地增加","correct":true},{"label":"指數增加","why":"解是 $t\\sin\\omega_0t$，前面是 $t$ 不是 $e^t$，振幅線性長大。"},{"label":"維持固定","why":"那是非共振的情形；共振時多出來的 $t$ 讓振幅一直變大。"}]},{"ask":"有阻尼（$\\gamma>0$）時，外力頻率 $\\omega=\\omega_0$ 的穩態振幅是？","options":[{"label":"有限值 $\\frac{F_0}{2\\gamma\\omega_0}$","correct":true},{"label":"無限大","why":"$\\gamma>0$ 時分母剩下 $(2\\gamma\\omega_0)^2$，不是 $0$；阻尼限制了振幅。"},{"label":"$0$","why":"$\\omega=\\omega_0$ 時分母最接近最小值，振幅接近最大，不是 $0$。"}]},{"ask":"$\\omega_0=10$、$\\gamma=6$，穩態振幅最大的外力頻率是？","options":[{"label":"$\\sqrt{28}\\approx5.29$","correct":true},{"label":"$10$","why":"那是 $\\omega_0$，只有沒有阻尼時峰才在那裡；有阻尼時峰在 $\\sqrt{100-2\\cdot36}$。"},{"label":"$8$","why":"$8$ 是 $\\omega_d=\\sqrt{100-36}$，自由振動的頻率；振幅峰值的公式是 $\\omega_0^2-2\\gamma^2$。"}]}],"practice":[{"id":"ode-p2-006","core":true}]}});
